      "content": "{\n  \"name\": \"dsh-session-sync\",\n  \"description\": \"Cross-device sync for DeepSeek Harness sessions: a dedicated git mirror of the session store, append-only three-way merge with keep-both + fork conflict resolution, /sync command, sync_pull/sync_push/sync_status tools, and configurable auto push/pull\",\n  \"version\": \"0.3.1\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/PerryLink/dsh-session-sync.git\"\n  },\n  \"homepage\": \"https://github.com/PerryLink/dsh-session-sync#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/PerryLink/dsh-session-sync/issues\"\n  },\n  \"author\": \"PerryLink\",\n  \"type\": \"module\",\n  \"main\": \"./index.mjs\",\n  \"types\": \"./types.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./types.d.ts\",\n      \"default\": \"./index.mjs\"\n    },\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"index.mjs\",\n    \"types.d.ts\",\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.en.md\",\n    \"README.es.md\",\n    \"README.pt.md\",\n    \"README.hi.md\",\n    \"ARCHITECTURE.md\",\n    \"CHANGELOG.md\",\n    \"SECURITY.md\",\n    \"LICENSE\",\n    \"THIRD_PARTY_NOTICES.md\",\n    \"PRIVACY.md\",\n    \"icon.svg\"\n  ],\n  \"dsh\": {\n    \"manifestVersion\": 1,\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"capabilities\": [\n      \"network:egress\",\n      \"subprocess\"\n    ],\n    \"labels\": []\n  },\n  \"dshWorkshop\": {\n    \"schema\": \"omdsh-workshop-package/v1\",\n    \"type\": \"plugin\",\n    \"integration\": {\n      \"protocol\": \"harness-profile\",\n      \"artifact\": \"cordis.patch.yml\"\n    },\n    \"install\": {\n      \"mode\": \"transactional\",\n      \"adapter\": \"profile-bundle\",\n      \"failurePolicy\": \"generation-rollback\",\n      \"touchesCurrentBeforeActivation\": false\n    },\n    \"