": \"0.2.2-rc.3\",\n    \"@deepseek-ai/dsh-user-questions\": \"0.2.2-rc.3\",\n    \"@deepseek-ai/schemastery\": \"~3.19.0\",\n    \"@types/node\": \"^22.19.0\",\n    \"oxlint\": \"0.18.1\",\n    \"typescript\": \"^5.9.0\",\n    \"@deepseek-ai/dsh-working-directory\": \"0.2.2-rc.3\",\n    \"@deepseek-ai/dsh-package-manifest\": \"0.2.2-rc.3\"\n  },\n  \"scripts\": {\n    \"typecheck\": \"tsc -p tsconfig.check.json\",\n    \"typecheck:ci\": \"tsc -p tsconfig.check.ci.json\",\n    \"test\": \"node --test \\\"test/*.test.mjs\\\"\",\n    \"coverage\": \"node --test --experimental-test-coverage \\\"test/*.test.mjs\\\"\",\n    \"lint\": \"oxlint\",\n    \"verify:self-contained\": \"node scripts/verify-self-contained.mjs\",\n    \"check:lockfile\": \"node scripts/check-lockfile-drift.mjs\",\n    \"verify:artifacts\": \"node scripts/verify-artifacts.mjs\",\n    \"check:readmes\": \"node scripts/verify-readmes.mjs\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"deepseek\",\n    \"cordis\",\n    \"session-sync\",\n    \"session\",\n    \"git\",\n    \"sync\",\n    \"cross-device\"\n  ],\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.9.0\",\n    \"dsh\": \">=0.1.2-rc.1 <0.2.0 || >=0.1.5-alpha.1 <0.2.0 || >=0.1.6-0 <0.2.0 || >=0.1.7-0 <0.2.0 || >=0.2.0-0 <0.3.0 || >=0.2.1-0 <0.3.0 || >=0.2.2-0 <0.3.0\"\n  },\n  \"packageManager\": \"pnpm@11.7.0\",\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"license\": \"Apache-2.0\",\n  \"funding\": {\n    \"type\": \"individual\",\n    \"url\": \"https://github.com/sponsors/PerryLink\"\n  },\n  \"icon\": \"icon.svg\"\n}\n"
