      "path": "index.mjs",
      "content": "// index.mjs — dsh-session-sync 插件入口（唯一 host 面文件）。\n//\n// 功能：把 DSH 会话存储目录（默认 $DSH_HOME/sessions）作为不透明字节镜像进\n// 一个专用 git 工作树并同步到自定义 remote：\n// - 默认 git 后端（ctx.subprocess 跑 git；动词白名单 + 绝不强推）；backend 词汇\n//   预留端到端加密后端（age/GPG 类），密钥不入仓库（当前配置即响亮失败）。\n// - /sync 命令（status|pull|push|diff|log|help；pull/push 走确认门）与\n//   sync_pull / sync_push / sync_status 模型工具（操作走审批，轮次内可用）。\n// - 冲突裁决：会话日志 append-only —— 双边纯追加/真实分歧一律\"本地保留 +\n//   远端留存 fork 文件\"，绝不静默覆盖（lib/merge.mjs 语义 + 测试）。\n// - 自动模式：autoPullOnStart / autoPushOnTurnEnd（turn/end 会话事件）/\n//   pullIntervalMinutes（周期拉取；定时与事件全部走 ctx.effect 可逆）。\n// - 同步元数据（设备 id、最近推/拉、最近错误）存 ctx.storageDomain 领域\n//   'session-sync'。\n//\n// 只消费公开服务：sessions / commands / storageDomain / subprocess（inject\n// 声明），tools 经 ctx.inject 可选注册；userQuestions / approval 可选查找\n// （缺失 = 失败关闭）。lib/ 零 DSH 依赖，服务只在边界接线。\n\nimport { randomUUID } from 'node:crypto'\nimport { Context } from '@deepseek-ai/cordis'\nimport Schema from '@deepseek-ai/schemastery'\nimport SessionStore, { KNOWN_SESSION_EVENT_TYPES } from '@deepseek-ai/dsh-session'\nimport { createUserMessage } from '@deepseek-ai/dsh-llm'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport {\n  BACKENDS,\n  COMMAND_NAME,\n  CONFIRM_CHANNELS,\n  DEFAULTS,\n  LIMITS,\n  PLUGIN_NAME,\n  SESSION_EVENTS,\n  STATE_KEY,\n  TOOL_PULL,\n  TOOL_PUSH,\n  TOOL_STATUS,\n} from './lib/constants.mjs'\nimport {\n  badConfig,\n  backendUnsupported,\n  messageOf,\n  registryUnavailable,\n} from './lib/errors.mjs'\nimport {\n  assertNestingSafe,\n  resolveRepoDir,\n  resolveSessionRoot,\n  sessionIdOfForkPath,\n} from './lib/paths.mjs'\nimport { GitBackend } from './lib/git.mjs'\nimport { SyncEngine } from './lib/engine.mjs'\nimport { EncryptedBackend, encryptTree, decryptTree, mergeTrees } from './lib/encrypted.mjs'\nimport { selectEncryptionMode } from './lib/backend.mjs'\nimport { detectAge, ageEncrypt, ageDecrypt } from './lib/age.mjs'\nimport { collectStatus } from './lib/status.mjs'\nimport { renderDiff, renderPull, renderPush, renderStatus, errorValue } from './lib/render.mjs'\nimport { confirmSync, hasOpenTurn, makeEventGate, maybeAppendSessionEvent, openTurnFromProjection } from './lib/gate.mjs'\nimport { sessionSyncDomainSpec } from './lib/domain.mjs'\nimport { waitForSessionDurability } from './lib/durability.mjs'\nimport {\n  matchCwdMap,\n  normalizeCwdMap,\n  projectCwd,\n  projectKey,\n  projectedRelOf,\n} from './lib/cwdmap.mjs'\nimport {\n  canonicalizeProjectedFile,\n  planRestoreFile,\n  readProjectionState,\n} from './lib/projection.mjs'\nimport { readSessionHeader } from './lib/sessionlog.mjs'\n\nexport const name = PLUGIN_NAME\n\n/** 必需服务：缺失即加载失败（响亮）。 */\nexport const inject = ['sessions', 'commands', 'storageDomain', 'subprocess']\n\n/**\n * 宿主 append 是否盖章 ignorable 信封（运行时能力探测）。\n * 在全新 detached Context 上构造 SessionStore（绝不接入宿主持久化，探测\n * 会话不落盘）：追加一条带 { ignorable: true } 的探测事件并回读信封标记。\n * rc.6 的 append 静默丢弃未知选项键；rc.8/rc.2 的 append 对非 surface 类型不接受\n * 信封选项（ignorable 只是读取路径的标记）→ 探测事件均无 ignorable →\n * false（门保持关闭）；\n * append 会盖章 ignorable 信封的宿主 → true（sync/* 以 ignorable 落盘）。\n * @returns {boolean} 宿主支持 ignorable 信封。\n */\nexport function probeIgnorableAppend() {\n  try {\n    const store = new SessionStore(new Context())\n    const session = store.create()\n    const event = session.append(SESSION_EVENTS.PUSH, {\n      sessionId: 'probe',\n      ok: true,\n      pushed: true,\n      head: 'probe',\n      // @ts-ignore non-surface append takes no envelope option — probing it is the point.\n    }, /** @type {any} */ ({ ignorable: true }))\n    return event?.ignorable === true\n  } catch {\n    return false\n  }\n}\n\n/**\n * 插件配置（Schemastery，全部可 cordis.yml 覆盖；无硬编码 tunable）。\n * @typedef {object} Config\n * @property {boolean} [enabled] 整体开关；false 时不注册任何东西。\n * @property {string} [backend] 同步后端词汇；只有 'git' 实现，其余（加密后端）预留并响亮失败。\n * @property {string} [sessionRoot] 会话存储根；空 = $DSH_HOME/sessions（两者皆缺响亮失败）。\n * @property {string} [repoDir] 同步 git 工作树根；空 = $DSH_HOME/dsh-session-sync/repo。\n * @property {string} [remote] 远端地址（自定义 remote；pull/push 前必须非空，status/diff 不需要）。\n * @property {string} [branch] 远端分支名（默认 main）。\n * @property {string} [gitBin] git 可执行路径（默认 'git'）。\n * @property {string} [ageBin] age 可执行路径（默认 'age'；backend: encrypted 时探测，缺失降级明文）。\n * @property {string} [ageRecipient] age 收件人（公钥/身份串；空 = 无法加密，降级明文）。\n * @property {string} [ageIdentity] age 身份文件路径（无口令私钥；空 = 无法解密，降级明文）。\n * @property {boolean} [autoPullOnStart] 挂载时自动拉取一次（配置即授权，不再确认）。\n * @property {boolean} [autoPushOnTurnEnd] 每个 turn/end 后自动推送（配置即授权）。\n * @property {number} [durabilityTimeoutMs] 自动推送前等该会话落盘的上限 ms（宿主 JSONL 有 200ms 批量写窗；0 = 不等待，超时只记日志并继续）。\n * @property {number} [pullIntervalMinutes] 周期自动拉取间隔分钟（0 = 关闭）。\n * @property {'auto'|'userQuestions'|'approval'} [confirmVia] 确认通道（auto 优先 userQuestions）。\n * @property {ReadonlyArray<{from: string, to: string}>} [cwdMap] 恢复期 cwd 投影表（最长前缀优先；未命中的跨平台 cwd 归一到 sessionRoot/--unmapped--）。\n * @property {boolean} [followSessionSymlinks] 镜像时是否跟随 realpath 仍在 sessionRoot 内的符号链接（默认 false）。\n * @property {number} [graceMs] git 子进程终止宽限（ms）。\n * @property {number} [commandTimeoutMs] 单条 git 命令超时（ms）。\n * @property {number} [maxOutputBytes] git 输出单流收集上限（字节）。\n * @property {string} [commitName] 插件提交者名。\n * @property {string} [commitEmail] 插件提交者邮箱。\n * @property {boolean} [registerCommand] 注册 /sync 命令。\n * @property {boolean} [registerTools] tools 服务存在时注册 sync_* 工具。\n */\n// Service Definition — Config: the plugin's public configuration contract\n// (Schemastery schema), validated loudly at load by resolveConfig.\nexport const Config = Schema.object({\n  enabled: Schema.boolean().default(DEFAULTS.ENABLED),\n  backend: Schema.union(Object.values(BACKENDS)).default(DEFAULTS.BACKEND),\n  sessionRoot: Schema.string().default(DEFAULTS.SESSION_ROOT),\n  repoDir: Schema.string().default(DEFAULTS.REPO_DIR),\n  remote: Schema.string().default(DEFAULTS.REMOTE),\n  branch: Schema.string().default(DEFAULTS.BRANCH),\n  gitBin: Schema.string().default(DEFAULTS.GIT_BIN),\n  ageBin: Schema.string().default(DEFAULTS.AGE_BIN),\n  ageRecipient: Schema.string().default(DEFAULTS.AGE_RECIPIENT),\n  ageIdentity: Schema.string().default(DEFAULTS.AGE_IDENTITY),\n  autoPullOnStart: Schema.boolean().default(DEFAULTS.AUTO_PULL_ON_START),\n  autoPushOnTurnEnd: Schema.boolean().default(DEFAULTS.AUTO_PUSH_ON_TURN_END),\n  durabilityTimeoutMs: Schema.number().default(DEFAULTS.DURABILITY_TIMEOUT_MS),\n  pullIntervalMinutes: Schema.number().default(DEFAULTS.PULL_INTERVAL_MINUTES),\n  confirmVia: Schema.union(Object.values(CONFIRM_CHANNELS)).default(DEFAULTS.CONFIRM_VIA),\n  cwdMap: Schema.array(Schema.object({\n    from: Schema.string().required(),\n    to: Schema.string().required(),\n  })).default([...DEFAULTS.CWD_MAP]),\n  followSessionSymlinks: Schema.boolean().default(DEFAULTS.FOLLOW_SESSION_SYMLINKS),\n  graceMs: Schema.number().default(DEFAULTS.GRACE_MS),\n  commandTimeoutMs: Schema.number().default(DEFAULTS.COMMAND_TIMEOUT_MS),\n  maxOutputBytes: Schema.number().default(DEFAULTS.MAX_OUTPUT_BYTES),\n  commitName: Schema.string().default(DEFAULTS.COMMIT_NAME),\n  commitEmail: Schema.string().default(DEFAULTS.COMMIT_EMAIL),\n  registerCommand: Schema.boolean().default(DEFAULTS.REGISTER_COMMAND),\n  registerTools: Schema.boolean().default(DEFAULTS.REGISTER_TOOLS),\n})\n\n/**\n * 显式补齐默认 + 加载期校验（非法配置响亮失败）。\n * @param {Partial<Config>|undefined} config - cordis loader 传入的配置。\n * @returns {Required<Config>} 校验后的配置。\n */\nexport function resolveConfig(config = {}) {\n  const resolved = {\n    enabled: config.enabled ?? DEFAULTS.ENABLED,\n    backend: config.backend ?? DEFAULTS.BACKEND,\n    sessionRoot: config.sessionRoot ?? DEFAULTS.SESSION_ROOT,\n    repoDir: config.repoDir ?? DEFAULTS.REPO_DIR,\n    remote: config.remote ?? DEFAULTS.REMOTE,\n    branch: config.branch ?? DEFAULTS.BRANCH,\n    gitBin: config.gitBin ?? DEFAULTS.GIT_BIN,\n    ageBin: config.ageBin ?? DEFAULTS.AGE_BIN,\n    ageRecipient: config.ageRecipient ?? DEFAULTS.AGE_RECIPIENT,\n    ageIdentity: config.ageIdentity ?? DEFAULTS.AGE_IDENTITY,\n    autoPullOnStart: config.autoPullOnStart ?? DEFAULTS.AUTO_PULL_ON_START,\n    autoPushOnTurnEnd: config.autoPushOnTurnEnd ?? DEFAULTS.AUTO_PUSH_ON_TURN_END,\n    durabilityTimeoutMs: config.durabilityTimeoutMs ?? DEFAULTS.DURABILITY_TIMEOUT_MS,\n    pullIntervalMinutes: config.pullIntervalMinutes ?? DEFAULTS.PULL_INTERVAL_MINUTES,\n    confirmVia: config.confirmVia ?? DEFAULTS.CONFIRM_VIA,\n    cwdMap: normalizeCwdMap(config.cwdMap ?? DEFAULTS.CWD_MAP),\n    followSessionSymlinks: config.followSessionSymlinks ?? DEFAULTS.FOLLOW_SESSION_SYMLINKS,\n    graceMs: config.graceMs ?? DEFAULTS.GRACE_MS,\n    commandTimeoutMs: config.commandTimeoutMs ?? DEFAULTS.COMMAND_TIMEOUT_MS,\n    maxOutputBytes: config.maxOutputBytes ?? DEFAULTS.MAX_OUTPUT_BYTES,\n    commitName: config.commitName ?? DEFAULTS.COMMIT_NAME,\n    commitEmail: config.commitEmail ?? DEFAULTS.COMMIT_EMAIL,\n    registerCommand: config.registerCommand ?? DEFAULTS.REGISTER_COMMAND,\n    registerTools: config.registerTools ?? DEFAULTS.REGISTER_TOOLS,\n  }\n  if (resolved.enabled === false) return resolved\n  if (!Object.values(BACKENDS).includes(/** @type {any} */ (resolved.backend))) {\n    throw backendUnsupported(/** @type {any} */ (resolved.backend))\n  }\n  if (!Object.values(CONFIRM_CHANNELS).includes(resolved.confirmVia)) {\n    throw badConfig(`confirmVia ${JSON.stringify(resolved.confirmVia)} must be one of auto|userQuestions|approval`)\n  }\n  if (typeof resolved.gitBin !== 'string' || resolved.gitBin.length === 0) {\n    throw badConfig('gitBin must be a non-empty string')\n  }\n  if (typeof resolved.ageBin !== 'string' || resolved.ageBin.length === 0) {\n    throw badConfig('ageBin must be a non-empty string')\n  }\n  if (typeof resolved.ageRecipient !== 'string') {\n    throw badConfig('ageRecipient must be a string')\n  }\n  if (typeof resolved.ageIdentity !== 'string') {\n    throw badConfig('ageIdentity must be a string')\n  }\n  if (typeof resolved.branch !== 'string' || resolved.branch.length === 0 || !/^[A-Za-z0-9._/-]+$/u.test(resolved.branch)) {\n    throw badConfig('branch must be a non-empty ref-safe string')\n  }\n  if (!Number.isFinite(resolved.graceMs) || resolved.graceMs < LIMITS.MIN_GRACE_MS || resolved.graceMs > LIMITS.MAX_GRACE_MS) {\n    throw badConfig(`graceMs must be an integer in [${LIMITS.MIN_GRACE_MS}, ${LIMITS.MAX_GRACE_MS}]`)\n  }\n  if (!Number.isFinite(resolved.commandTimeoutMs) || resolved.commandTimeoutMs < LIMITS.MIN_COMMAND_TIMEOUT_MS || resolved.commandTimeoutMs > LIMITS.MAX_COMMAND_TIMEOUT_MS) {\n    throw badConfig(`commandTimeoutMs must be an integer in [${LIMITS.MIN_COMMAND_TIMEOUT_MS}, ${LIMITS.MAX_COMMAND_TIMEOUT_MS}]`)\n  }\n  if (!Number.isFinite(resolved.maxOutputBytes) || resolved.maxOutputBytes < LIMITS.MIN_MAX_OUTPUT_BYTES || resolved.maxOutputBytes > LIMITS.MAX_MAX_OUTPUT_BYTES) {\n    throw badConfig(`maxOutputBytes must be an integer in [${LIMITS.MIN_MAX_OUTPUT_BYTES}, ${LIMITS.MAX_MAX_OUTPUT_BYTES}]`)\n  }\n  if (!Number.isInteger(resolved.pullIntervalMinutes) || resolved.pullIntervalMinutes < LIMITS.MIN_PULL_INTERVAL_MINUTES || resolved.pullIntervalMinutes > LIMITS.MAX_PULL_INTERVAL_MINUTES) {\n    throw badConfig(`pullIntervalMinutes must be an integer in [${LIMITS.MIN_PULL_INTERVAL_MINUTES}, ${LIMITS.MAX_PULL_INTERVAL_MINUTES}]`)\n  }\n  if (!Number.isInteger(resolved.durabilityTimeoutMs) || resolved.durabilityTimeoutMs < LIMITS.MIN_DURABILITY_TIMEOUT_MS || resolved.durabilityTimeoutMs > LIMITS.MAX_DURABILITY_TIMEOUT_MS) {\n    throw badConfig(`durabilityTimeoutMs must be an integer in [${LIMITS.MIN_DURABILITY_TIMEOUT_MS}, ${LIMITS.MAX_DURABILITY_TIMEOUT_MS}]`)\n  }\n  if (typeof resolved.followSessionSymlinks !== 'boolean') {\n    throw badConfig('followSessionSymlinks must be a boolean')\n  }\n  if (typeof resolved.commitName !== 'string' || resolved.commitName.trim().length === 0) {\n    throw badConfig('commitName must be a non-empty string')\n  }\n  if (typeof resolved.commitEmail !== 'string' || resolved.commitEmail.trim().length === 0) {\n    throw badConfig('commitEmail must be a non-empty string')\n  }\n  if (resolved.sessionRoot === '' && process.env.DSH_HOME === undefined) {\n    throw badConfig('sessionRoot is empty and $DSH_HOME is not set; run under dsh or set sessionRoot explicitly')\n  }\n  if (resolved.repoDir === '' && process.env.DSH_HOME === undefined) {\n    throw badConfig('repoDir is empty and $DSH_HOME is not set; run under dsh or set repoDir explicitly')\n  }\n  return resolved\n}\n\n/**\n * git runner：ctx.subprocess 上的 collect/pipe 封装。\n * binary=true 时 stdout 走原始字节管道（读 blob 必需），否则 collect 文本。\n * @param {import('@deepseek-ai/dsh-subprocess').SubprocessRuntime} subprocess - 宿主子进程服务。\n * @param {object} opts - {gitBin, graceMs, commandTimeoutMs, maxOutputBytes}。\n * @returns {(args: string[], runOpts?: object) => Promise<{code: number, stdout: string|Buffer, stderr: string}>}\n */\nexport function makeRunGit(subprocess, opts) {\n  return async (args, runOpts = {}) => {\n    const controller = new AbortController()\n    let timedOut = false\n    const timer = setTimeout(() => {\n      timedOut = true\n      controller.abort(new Error(`git ${args[0] ?? ''} timed out after ${opts.commandTimeoutMs}ms`))\n    }, opts.commandTimeoutMs)\n    const onAbort = () => {\n      controller.abort(runOpts.signal?.reason instanceof Error ? runOpts.signal.reason : new Error('sync operation aborted'))\n    }\n    if (runOpts.signal !== undefined) {\n      runOpts.signal.addEventListener('abort', onAbort, { once: true })\n    }\n    try {\n      const executable = await subprocess.resolveExecutable(opts.gitBin, undefined, controller.signal)\n      const handle = subprocess.spawn({\n        argv: [executable, ...args],\n        cwd: runOpts.cwd,\n        stdio: {\n          stdin: 'ignore',\n          stdout: runOpts.binary === true ? 'pipe' : { maxBytes: opts.maxOutputBytes },\n          stderr: { maxBytes: opts.maxOutputBytes },\n        },\n        graceMs: opts.graceMs,\n        signal: controller.signal,\n        env: {\n          GIT_TERMINAL_PROMPT: '0',\n          GIT_OPTIONAL_LOCKS: '0',\n        },\n      })\n      let raw\n      if (runOpts.binary === true) {\n        const chunks = []\n        for await (const chunk of handle.stdout) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk)))\n        raw = Buffer.concat(chunks)\n      }\n      const outcome = await handle.done\n      if (timedOut) {\n        throw new Error(`git ${args[0] ?? ''} timed out after ${opts.commandTimeoutMs}ms`)\n      }\n      if (runOpts.signal?.aborted === true) {\n        throw runOpts.signal.reason instanceof Error ? runOpts.signal.reason : new Error('sync operation aborted')\n      }\n      const stdout = raw ?? handle.collected.stdout.readFrom(0).text\n      const stderr = handle.collected.stderr.readFrom(0).text\n      return { code: outcome.exitCode ?? (outcome.signal !== null ? 128 : 0), stdout, stderr }\n    } finally {\n      clearTimeout(timer)\n      if (runOpts.signal !== undefined) {\n        runOpts.signal.removeEventListener('abort', onAbort)\n      }\n    }\n  }\n}\n\n/**\n * age runner：ctx.subprocess 上的 collect 封装（与 makeRunGit 同构）。\n * args 为「含可执行路径的完整 argv」（lib/age.mjs 的 runner 契约），只做文本\n * 输出收集与退出码/超时/取消语义；age 加解密经文件入参（-o out in），无需 stdin。\n * @param {import('@deepseek-ai/dsh-subprocess').SubprocessRuntime} subprocess - 宿主子进程服务。\n * @param {object} opts - {graceMs, commandTimeoutMs, maxOutputBytes}。\n * @returns {(args: string[], runOpts?: object) => Promise<{code: number, stdout: string, stderr: string}>}\n */\nexport function makeRunAge(subprocess, opts) {\n  return async (args, runOpts = {}) => {\n    const controller = new AbortController()\n    let timedOut = false\n    const timer = setTimeout(() => {\n      timedOut = true\n      controller.abort(new Error(`age ${args[0] ?? ''} timed out after ${opts.commandTimeoutMs}ms`))\n    }, opts.commandTimeoutMs)\n    const onAbort = () => {\n      controller.abort(runOpts.signal?.reason instanceof Error ? runOpts.signal.reason : new Error('sync operation aborted'))\n    }\n    if (runOpts.signal !== undefined) {\n      runOpts.signal.addEventListener('abort', onAbort, { once: true })\n    }\n    try {\n      const executable = await subprocess.resolveExecutable(args[0], undefined, controller.signal)\n      const handle = subprocess.spawn({\n        argv: [executable, ...args.slice(1)],\n        cwd: runOpts.cwd,\n        stdio: {\n          stdin: 'ignore',\n          stdout: { maxBytes: opts.maxOutputBytes },\n          stderr: { maxBytes: opts.maxOutputBytes },\n        },\n        graceMs: opts.graceMs,\n        signal: controller.signal,\n      })\n      const outcome = await handle.done\n      if (timedOut) {\n        throw new Error(`age ${args[0] ?? ''} timed out after ${opts.commandTimeoutMs}ms`)\n      }\n      if (runOpts.signal?.aborted === true) {\n        throw runOpts.signal.reason instanceof Error ? runOpts.signal.reason : new Error('sync operation aborted')\n      }\n      const stdout = handle.collected.stdout.readFrom(0).text\n      const stderr = handle.collected.stderr.readFrom(0).text\n      return { code: outcome.exitCode ?? (outcome.signal !== null ? 128 : 0), stdout, stderr }\n    } finally {\n      clearTimeout(timer)\n      if (runOpts.signal !== undefined) {\n        runOpts.signal.removeEventListener('abort', onAbort)\n      }\n    }\n  }\n}\n\n/**\n * 工具参数/输出描述（双语）。\n */\nconst TOOL_TEXT = {\n  en: {\n    statusDescription: 'Show the session-sync git mirror state: branch, sanitized remote, ahead/behind counts, uncommitted files, fork files from conflicts, and the last pull/push times. Read-only: never confirms, never touches the network.',\n    pullDescription: 'Pull remote session changes into the local sync mirror with append-only keep-both merge semantics (local version kept, remote version preserved as fork files — never silently overwritten). Requires user confirmation.',\n    pushDescription: 'Mirror local session files into the sync repo, commit, and push to the configured remote. Never force-pushes; a rejected push reconciles by pulling first and retries once. Requires user confirmation.',\n  },\n}\n\n/** sync_status 工具规范结果（与工具 schema 同构）。 */\n/** @typedef {{ok: boolean, branch: string, remote: string, head?: string, remoteHead?: string, ahead: number, behind: number, dirty: string[], forks: string[], diffStat: string, mergeInProgress: boolean, lastCommits: string[], lastPullAt?: number, lastPushAt?: number, lastError?: string, error?: string, skippedSymlinks?: number, skippedSymlinkPaths?: string[], followedSymlinks?: number, cwdMapped?: number, cwdUnmapped?: number, cwdProjectionSkipped?: number, cwdPlaceholder?: string, followSessionSymlinks?: boolean, warnings?: string[]}} StatusValue */\n/** @typedef {{ok: boolean, pulled?: boolean, merged?: boolean, adopted?: number, appended?: number, diverged?: number, forks?: string[], head?: string, restored?: number, cwdMapped?: number, cwdUnmapped?: number, error?: string, warnings?: string[]}} PullValue */\n/** @typedef {{ok: boolean, pushed?: boolean, head?: string, mirrored?: number, deleted?: number, remote?: string, skippedSymlinks?: number, skippedSymlinkPaths?: string[], error?: string, warnings?: string[]}} PushValue */\n\n/**\n * sync_status 工具定义（read-only：不确认、不触网）。\n * @param {{status: () => Promise<object>}} engine - 同步引擎（git 或 encrypted 后端同一 surface）。\n * @param {() => Promise<object>} readMeta - 元数据读取。\n * @returns {object} 工具定义。\n */\nexport function makeSyncStatusTool(engine, readMeta) {\n  return defineTool({\n    name: TOOL_STATUS,\n    description: TOOL_TEXT.en.statusDescription,\n    parameters: {},\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          ok: { type: 'boolean', required: true },\n          branch: { type: 'string' },\n          remote: { type: 'string' },\n          head: { type: 'string' },\n          remoteHead: { type: 'string' },\n          ahead: { type: 'integer' },\n          behind: { type: 'integer' },\n          dirty: { type: 'array', items: { type: 'string' } },\n          forks: { type: 'array', items: { type: 'string' } },\n          diffStat: { type: 'string' },\n          mergeInProgress: { type: 'boolean' },\n          lastCommits: { type: 'array', items: { type: 'string' } },\n          lastPullAt: { type: 'integer' },\n          lastPushAt: { type: 'integer' },\n          lastError: { type: 'string' },\n          error: { type: 'string' },\n          skippedSymlinks: { type: 'integer' },\n          skippedSymlinkPaths: { type: 'array', items: { type: 'string' } },\n          followedSymlinks: { type: 'integer' },\n          cwdMapped: { type: 'integer' },\n          cwdUnmapped: { type: 'integer' },\n          cwdProjectionSkipped: { type: 'integer' },\n          cwdPlaceholder: { type: 'string' },\n          followSessionSymlinks: { type: 'boolean' },\n          warnings: { type: 'array', items: { type: 'string' } },\n        },\n      },\n      render(_args, value) {\n        return [{ type: 'text', text: renderStatus(value) }]\n      },\n    },\n    async execute(_args, exec) {\n      exec.signal?.throwIfAborted()\n      const status = await engine.status()\n      try {\n        const meta = await readMeta()\n        // 只合并有值的键：把 undefined 展开进工具结果会让宿主按\n        // “value is not lossless JSON” 拒绝整个 sync_status 结果（#29）。\n        const extra = {}\n        if (meta.lastPullAt !== undefined) extra.lastPullAt = meta.lastPullAt\n        if (meta.lastPushAt !== undefined) extra.lastPushAt = meta.lastPushAt\n        if (meta.lastError !== undefined) extra.lastError = meta.lastError\n        const out = { ...status, ...extra }\n        // 工具结果必须是 lossless JSON：collectStatus 的 head/remoteHead/error\n        // 在空仓库或未配置远端时是 undefined，展开后会让宿主拒绝整个结果。\n        for (const key of Object.keys(out)) if (out[key] === undefined) delete out[key]\n        return out\n      } catch {\n        return status\n      }\n    },\n  })\n}\n\n/**\n * sync_pull 工具定义（操作走确认门；execute 尊重 exec.signal）。\n * @param {object} deps - {engine, ctx, confirmVia}。\n * @returns {object} 工具定义。\n */\nexport function makeSyncPullTool(deps) {\n  return defineTool({\n    name: TOOL_PULL,\n    description: TOOL_TEXT.en.pullDescription,\n    parameters: {},\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          ok: { type: 'boolean', required: true },\n          pulled: { type: 'boolean' },\n          merged: { type: 'boolean' },\n          adopted: { type: 'integer' },\n          appended: { type: 'integer' },\n          diverged: { type: 'integer' },\n          forks: { type: 'array', items: { type: 'string' } },\n          head: { type: 'string' },\n          restored: { type: 'integer' },\n          cwdMapped: { type: 'integer' },\n          cwdUnmapped: { type: 'integer' },\n          error: { type: 'string' },\n          warnings: { type: 'array', items: { type: 'string' } },\n        },\n      },\n      render(_args, value) {\n        return [{ type: 'text', text: renderPull(value) }]\n      },\n    },\n    async execute(_args, exec) {\n      exec.signal?.throwIfAborted()\n      const verdict = await confirmSync(\n        { ctx: deps.ctx, confirmVia: deps.confirmVia, action: 'pull', summary: 'Download remote session changes into the local sync mirror (keep-both merge; never overwrites).' },\n        exec.agent,\n        exec.signal,\n      )\n      if (!verdict.allowed) {\n        return errorValue(verdict.reason ?? 'confirmation failed (fail closed)')\n      }\n      const result = await deps.engine.pull({ signal: exec.signal })\n      if (exec.agent?.session !== null && exec.agent?.session !== undefined) {\n        maybeAppendSessionEvent(exec.agent.session, SESSION_EVENTS.PULL, {\n          sessionId: exec.agent.session.id,\n          ok: result.ok,\n          error: result.error,\n          pulled: result.pulled,\n          merged: result.merged,\n          adopted: result.adopted,\n          appended: result.appended,\n          diverged: result.diverged,\n          forks: result.forks,\n          head: result.head,\n        }, deps.eventGate, (message) => deps.logger.warn(message))\n      }\n      return result\n    },\n  })\n}\n\n/**\n * sync_push 工具定义（操作走确认门；execute 尊重 exec.signal）。\n * @param {object} deps - {engine, ctx, confirmVia, eventGate, logger}。\n * @returns {object} 工具定义。\n */\nexport function makeSyncPushTool(deps) {\n  return defineTool({\n    name: TOOL_PUSH,\n    description: TOOL_TEXT.en.pushDescription,\n    parameters: {},\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          ok: { type: 'boolean', required: true },\n          pushed: { type: 'boolean' },\n          head: { type: 'string' },\n          mirrored: { type: 'integer' },\n          deleted: { type: 'integer' },\n          remote: { type: 'string' },\n          skippedSymlinks: { type: 'integer' },\n          skippedSymlinkPaths: { type: 'array', items: { type: 'string' } },\n          error: { type: 'string' },\n          warnings: { type: 'array', items: { type: 'string' } },\n        },\n      },\n      render(_args, value) {\n        return [{ type: 'text', text: renderPush(value) }]\n      },\n    },\n    async execute(_args, exec) {\n      exec.signal?.throwIfAborted()\n      const verdict = await confirmSync(\n        { ctx: deps.ctx, confirmVia: deps.confirmVia, action: 'push', summary: 'Upload local session changes to the sync remote (commit + push; never force-pushes).' },\n        exec.agent,\n        exec.signal,\n      )\n      if (!verdict.allowed) {\n        return errorValue(verdict.reason ?? 'confirmation failed (fail closed)')\n      }\n      const result = await deps.engine.push({ signal: exec.signal })\n      if (exec.agent?.session !== null && exec.agent?.session !== undefined) {\n        maybeAppendSessionEvent(exec.agent.session, SESSION_EVENTS.PUSH, {\n          sessionId: exec.agent.session.id,\n          ok: result.ok,\n          error: result.error,\n          pushed: result.pushed,\n          mirrored: result.mirrored,\n          deleted: result.deleted,\n          head: result.head,\n        }, deps.eventGate, (message) => deps.logger.warn(message))\n      }\n      return result\n    },\n  })\n}\n\n/**\n * 向 fork 子会话注入冲突通知：说明远端版本已留存为 fork 文件、两边历史\n * 都完整。通知是持久的 user/message（本插件自有的 producer-owned source），\n * 派生历史会投影它。\n *\n * 宿主 0.1.7 起 `MessageSourceMap` 是**可合并扩展的联合**，没有共享的兜底\n * `plugin` kind；`{ kind: 'plugin' }` 已被退役（`session-format-v3-to-v4`\n * 的 `assertV4MessageSources` 直接拒收）。这里声明本插件自己的 kind —— 与\n * `types.d.ts` 的声明合并同名，缺一不可（见 test/source-readback.test.mjs）。\n * @param {import('@deepseek-ai/dsh-session').Session} child - fork 子会话。\n * @param {string[]} forkPaths - 本会话相关 fork 文件路径。\n * @param {string} parentId - 原会话 id。\n */\nexport function injectForkNotice(child, forkPaths, parentId) {\n  const text = [\n    'session-sync resolved a cross-device conflict by keeping both sides:',\n    `the local lineage of session ${parentId} continues here (this forked session);`,\n    'the remote version was preserved as fork file(s):',\n    ...forkPaths.slice(0, 10).map(path => `  ${path}`),\n    forkPaths.length > 10 ? `  … ${forkPaths.length - 10} more` : '',\n    'Both histories are intact in the sync repository; nothing was overwritten.',\n  ].filter(line => line.length > 0).join('\\n')\n  try {\n    /** @type {import('@deepseek-ai/dsh-llm').UserMessage} 冲突通知消息（本插件 producer-owned source）。 */\n    const notice = createUserMessage({\n      content: [{ type: 'text', text }],\n      source: { kind: 'dsh-session-sync', form: 'notice', summary: 'session-sync conflict fork' },\n    })\n    child.append('user/message', notice, { surfaceOp: 'append' })\n  } catch (error) {\n    // 通知是锦上添花：append 失败绝不能把一次成功的拉取变成失败。\n    return\n  }\n}\n\n/**\n * 插件挂载。enabled:false 时不注册任何东西；非法配置在加载期响亮抛错。\n * @param {import('@deepseek-ai/cordis').Context} ctx - Cordis 上下文。\n * @param {Partial<Config>} [config] - 插件配置。\n */\nexport function apply(ctx, config = {}) {\n  const resolved = resolveConfig(config)\n  if (resolved.enabled === false) return\n\n  const logger = ctx.logger(PLUGIN_NAME)\n  const warn = (message) => logger.warn(message)\n  const eventGate = makeEventGate(KNOWN_SESSION_EVENT_TYPES, probeIgnorableAppend())\n\n  const sessionRoot = resolveSessionRoot(resolved.sessionRoot)\n  const repoDir = resolveRepoDir(resolved.repoDir)\n  assertNestingSafe(sessionRoot, repoDir)\n\n  // --- 同步元数据：ctx.storageDomain 领域 'session-sync'（异步打开，操作路径 await）。\n  // V2 形态（A02）：effect 在 apply 帧内**同步注册**并持有打开句柄——异步 open 期间\n  // 卸载时，disposer 仍会等到 promise 落定后关闭句柄，不会出现「INACTIVE_EFFECT\n  // 吞掉注册 ⇒ 域句柄永不关闭」。拒绝显式处理（记录原因 + 一次可见告警），不再用\n  // 静默的 `.catch(() => {})` 掩盖。\n  /** @type {Promise<object>} 打开后的领域 state 表（消费方各自 await）。 */\n  let tablePromise\n  ctx.effect(() => {\n    const opened = ctx.storageDomain.open(sessionSyncDomainSpec)\n    tablePromise = opened.then((domain) => domain.table('state'))\n    tablePromise.catch((error) => {\n      warn(`storage domain open failed: ${error?.message ?? String(error)}`)\n    })\n    return () => {\n      void opened.then((domain) => domain.close()).catch((error) => {\n        warn(`storage domain close failed: ${error?.message ?? String(error)}`)\n      })\n    }\n  }, `${PLUGIN_NAME}.domain.close`)\n\n  /** @type {{deviceId: string, lastPullAt?: number, lastPushAt?: number, lastPushHead?: string, lastError?: string}|undefined} 元数据缓存。 */\n  let metaCache\n  let metaOps = Promise.resolve()\n  const withMeta = (fn) => {\n    const run = metaOps.then(fn, fn)\n    metaOps = run.then(() => undefined, () => undefined)\n    return run\n  }\n\n  /** 确保设备 id 已持久化并读入缓存。 */\n  async function ensureMeta() {\n    if (metaCache !== undefined) return metaCache\n    const table = await tablePromise\n    let state = await table.get(STATE_KEY)\n    if (state === undefined) {\n      state = { deviceId: randomUUID() }\n      await table.put(STATE_KEY, state)\n    }\n    metaCache = state\n    return state\n  }\n\n  /** 元数据补丁（引擎回调；串行写领域）。 */\n  function reportMeta(patch) {\n    void withMeta(async () => {\n      try {\n        const current = await ensureMeta()\n        const next = { ...current, ...patch }\n        // `undefined` 表示删除该键（清空 lastError），而不是写入一个非 JSON 值。\n        for (const key of Object.keys(patch)) if (patch[key] === undefined) delete next[key]\n        const table = await tablePromise\n        await table.put(STATE_KEY, next)\n        metaCache = next\n      } catch (error) {\n        warn(`sync metadata write failed: ${messageOf(error)}`)\n      }\n    })\n  }\n\n  /** 最近错误（引擎回调；串行写领域）。 */\n  function reportError(message) {\n    reportMeta({ lastError: message.slice(0, 500) })\n  }\n\n  // --- git 后端 + 引擎（backend seam：git = 明文，encrypted = age 加密的 git）。\n  const git = new GitBackend({\n    repoDir,\n    remote: resolved.remote,\n    branch: resolved.branch,\n    commitName: resolved.commitName,\n    commitEmail: resolved.commitEmail,\n    run: makeRunGit(ctx.subprocess, {\n      gitBin: resolved.gitBin,\n      graceMs: resolved.graceMs,\n      commandTimeoutMs: resolved.commandTimeoutMs,\n      maxOutputBytes: resolved.maxOutputBytes,\n    }),\n    timeoutMs: resolved.commandTimeoutMs,\n  })\n\n  const engineDeps = {\n    git,\n    sessionRoot,\n    repoDir,\n    remote: resolved.remote,\n    branch: resolved.branch,\n    deviceId: 'pending',\n    cwdMap: resolved.cwdMap,\n    followSessionSymlinks: resolved.followSessionSymlinks,\n    reportMeta,\n    reportError,\n    logger,\n    onForks: (forkPaths) => handleForks(forkPaths),\n  }\n  const engine = resolved.backend === BACKENDS.ENCRYPTED\n    ? new EncryptedBackend({\n        ...engineDeps,\n        run: makeRunAge(ctx.subprocess, {\n          graceMs: resolved.graceMs,\n          commandTimeoutMs: resolved.commandTimeoutMs,\n          maxOutputBytes: resolved.maxOutputBytes,\n        }),\n        ageBin: resolved.ageBin,\n        ageRecipient: resolved.ageRecipient,\n        ageIdentity: resolved.ageIdentity,\n        timeoutMs: resolved.commandTimeoutMs,\n      })\n    : new SyncEngine(engineDeps)\n  // 设备 id 来自元数据领域；在领域就绪后补齐（fork 命名/设备文件用）。\n  void ensureMeta().then((meta) => {\n    engine.deviceId = meta.deviceId\n  }).catch(error => warn(`sync metadata open failed: ${messageOf(error)}`))\n\n  /** fork 文件产生回调：尝试把冲突会话在会话层面 fork（安全时）。 */\n  function handleForks(forkPaths) {\n    const bySession = new Map()\n    let unmapped = 0\n    for (const forkPath of forkPaths) {\n      const sessionId = sessionIdOfForkPath(forkPath)\n      if (sessionId === undefined) {\n        unmapped += 1\n        continue\n      }\n      const list = bySession.get(sessionId) ?? []\n      list.push(forkPath)\n      bySession.set(sessionId, list)\n    }\n    if (unmapped > 0) {\n      logger.warn(`sync: ${unmapped} fork path(s) outside the project/session layout were not mapped to a session-level fork (files preserved)`)\n    }\n    for (const [sessionId, paths] of bySession) {\n      const session = ctx.sessions.get(sessionId)\n      if (session === undefined) continue\n      maybeAppendSessionEvent(session, SESSION_EVENTS.CONFLICT, {\n        sessionId: session.id,\n        forkPaths: paths,\n        diverged: paths.length,\n      }, eventGate, warn)\n      const openTurn = openTurnFromProjection(ctx, session)\n      if (openTurn !== false) {\n        // true=轮次进行中；undefined=投影缺席。两者都跳过会话级 fork：拿不到\n        // 权威轮次状态时绝不在可能开放的轮次里 fork，fork 文件仍全部保留。\n        logger.info(`sync conflict on live session ${sessionId}: ${openTurn === true ? 'turn open' : 'turn state unavailable (turnBoundary projection absent)'}, session-level fork skipped (files preserved as forks)`)\n        continue\n      }\n      try {\n        const child = ctx.sessions.fork(session)\n        injectForkNotice(child, paths, session.id)\n        maybeAppendSessionEvent(session, SESSION_EVENTS.CONFLICT, {\n          sessionId: session.id,\n          forkPaths: paths,\n          childSessionId: child.id,\n        }, eventGate, warn)\n        logger.info(`sync conflict on session ${sessionId}: forked → ${child.id} (both lineages kept)`)\n      } catch (error) {\n        logger.warn(`sync conflict session fork failed for ${sessionId}: ${messageOf(error)} (fork files preserved)`)\n      }\n    }\n  }\n\n  // Service Provider — /sync 命令注册进宿主 commands 服务；其 handler 是消费面（Consumer）。\n  if (resolved.registerCommand) {\n    ctx.commands.register({\n      name: COMMAND_NAME,\n      description: 'Cross-device session sync: status, pull/push the git mirror with keep-both conflict resolution, or diff against the last-fetched remote.',\n      input: { hint: '[status | pull | push | diff | log | help]' },\n      async handler(invocation) {\n        return handleSyncCommand(invocation)\n      },\n    })\n  }\n\n  /**\n   * /sync 命令处理器。\n   * @param {import('@deepseek-ai/dsh-commands').CommandInvocation} invocation - 命令调用。\n   * @returns {Promise<import('@deepseek-ai/dsh-commands').CommandResult>} 命令结果。\n   */\n  async function handleSyncCommand(invocation) {\n    const { agent, rawInput, signal } = invocation\n    const session = agent?.session\n    const action = rawInput.trim().split(/\\s+/u)[0]?.toLowerCase() || 'status'\n    try {\n      if (action === 'help' || (action !== 'status' && action !== 'pull' && action !== 'push' && action !== 'diff' && action !== 'log')) {\n        return {\n          kind: 'success',\n          text: [\n            'sync: usage — /sync [status | pull | push | diff | log | help]',\n            '  status  show mirror state (default): branch, remote, ahead/behind, dirty, forks',\n            '  pull    fetch + merge remote changes (keep-both; confirms first)',\n            '  push    mirror + commit + push local changes (confirms first)',\n            '  diff    uncommitted changes + HEAD..remote stat (read-only)',\n            '  log     last commits in the sync repository',\n          ].join('\\n'),\n        }\n      }\n      if (action === 'status') {\n        const status = await engine.status()\n        let meta = {}\n        try {\n          meta = await ensureMeta()\n        } catch {\n          // 元数据只读失败不阻断状态展示。\n        }\n        return { kind: status.ok ? 'success' : 'error', text: renderStatus({ ...status, lastPullAt: meta.lastPullAt, lastPushAt: meta.lastPushAt }) }\n      }\n      if (action === 'diff') {\n        const status = await engine.status()\n        return { kind: status.ok ? 'success' : 'error', text: renderDiff(status) }\n      }\n      if (action === 'log') {\n        const status = await engine.status()\n        const lines = status.lastCommits.length > 0 ? status.lastCommits : ['(no commits yet)']\n        return { kind: 'success', text: `sync: last commits in ${repoDir}:\\n${lines.map(line => `  ${line}`).join('\\n')}` }\n      }\n      // pull / push：覆盖性操作必须经确认门（无回答者失败关闭）。\n      const summary = action === 'push'\n        ? 'Local session files will be mirrored, committed, and pushed to the sync remote (never force-pushed).'\n        : 'Remote session changes will be merged into the local mirror with keep-both semantics (local kept, remote preserved as fork files).'\n      const verdict = await confirmSync({ ctx, confirmVia: resolved.confirmVia, action, summary }, agent, signal)\n      if (!verdict.allowed) {\n        const reason = verdict.reason ?? 'no confirmation answerer (fail closed)'\n        logger.info(`sync ${action} denied (${verdict.channel}: ${reason})`)\n        return { kind: 'error', text: `sync: cancelled: ${reason}` }\n      }\n      if (action === 'push') {\n        const result = await engine.push({ signal })\n        if (session !== null && session !== undefined) {\n          maybeAppendSessionEvent(session, SESSION_EVENTS.PUSH, {\n            sessionId: session.id,\n            ok: result.ok,\n            error: result.error,\n            pushed: result.pushed,\n            mirrored: result.mirrored,\n            deleted: result.deleted,\n            head: result.head,\n          }, eventGate, warn)\n        }\n        return { kind: result.ok ? 'success' : 'error', text: renderPush(result) }\n      }\n      const result = await engine.pull({ signal })\n      if (session !== null && session !== undefined) {\n        maybeAppendSessionEvent(session, SESSION_EVENTS.PULL, {\n          sessionId: session.id,\n          ok: result.ok,\n          error: result.error,\n          pulled: result.pulled,\n          merged: result.merged,\n          adopted: result.adopted,\n          appended: result.appended,\n          diverged: result.diverged,\n          forks: result.forks,\n          head: result.head,\n        }, eventGate, warn)\n      }\n      return { kind: result.ok ? 'success' : 'error', text: renderPull(result) }\n    } catch (error) {\n      const message = `sync: ${action || 'status'} failed: ${messageOf(error)}`\n      logger.error(message)\n      return { kind: 'error', text: message }\n    }\n  }\n\n  // --- sync_* 模型工具（Consumer；tools 服务存在时才注册，随 fiber 卸载撤销）。\n  if (resolved.registerTools) {\n    ctx.inject(['tools'], (toolCtx) => {\n      toolCtx.tools.register(makeSyncStatusTool(engine, ensureMeta))\n      toolCtx.tools.register(makeSyncPullTool({ engine, ctx, confirmVia: resolved.confirmVia, eventGate, logger }))\n      toolCtx.tools.register(makeSyncPushTool({ engine, ctx, confirmVia: resolved.confirmVia, eventGate, logger }))\n    })\n  }\n\n  // --- 自动模式（全部 effect：事件/定时随插件卸载自动撤销）。\n  // 挂载时自动拉取（配置即授权；失败只记日志，绝不阻断启动）。\n  if (resolved.autoPullOnStart) {\n    ctx.effect(() => {\n      void engine.pull().then(result => {\n        if (!result.ok) warn(`auto pull failed: ${result.error ?? 'unknown error'}`)\n      })\n      return () => {}\n    }, `${PLUGIN_NAME}.auto-pull-on-start`)\n  }\n\n  // turn/end 自动推送（配置即授权；每轮结束先等该会话落盘，再拉快照推送）。\n  if (resolved.autoPushOnTurnEnd) {\n    // #30：有些宿主（Android/proot 的 DSH Go）不发 session/event；把\"监听器已\n    // 注册\"记进日志，让外部可判断的是宿主事件还是插件注册。\n    logger.info(`auto push listener registered (session/event turn/end → push); pullIntervalMinutes=${resolved.pullIntervalMinutes}; durabilityTimeoutMs=${resolved.durabilityTimeoutMs}`)\n    let durabilityUnsupportedWarned = false\n    const autoPush = async (session) => {\n      // 宿主的 JSONL 持久化对 live 事件有 200ms 批量写窗（见 lib/durability.mjs）：\n      // 不等这层落盘屏障，镜像就会缺最后一条 turn/end —— 跨设备恢复会看到未闭合\n      // 轮次。等待有上限且绝不抛出：超时/失败只记日志，照常推送当前盘上快照。\n      const durability = await waitForSessionDurability(session, {\n        sessions: ctx.sessions,\n        timeoutMs: resolved.durabilityTimeoutMs,\n      })\n      if (durability.timedOut === true) {\n        warn(`auto push: session ${session.id} was not durable within ${resolved.durabilityTimeoutMs}ms; mirroring the current on-disk snapshot`)\n      } else if (durability.unsupported === true) {\n        if (!durabilityUnsupportedWarned) {\n          durabilityUnsupportedWarned = true\n          warn('auto push: this host exposes no sessions.flush(); mirroring without a durability wait (host older than 0.2.2)')\n        }\n      } else if (durability.error !== undefined) {\n        warn(`auto push: durability wait failed for session ${session.id}: ${durability.error}; mirroring the current on-disk snapshot`)\n      }\n      const result = await engine.push()\n      maybeAppendSessionEvent(session, SESSION_EVENTS.PUSH, {\n        sessionId: session.id,\n        ok: result.ok,\n        error: result.error,\n        pushed: result.pushed,\n        mirrored: result.mirrored,\n        deleted: result.deleted,\n        head: result.head,\n      }, eventGate, warn)\n      if (!result.ok) warn(`auto push failed: ${result.error ?? 'unknown error'}`)\n    }\n    ctx.on('session/event', (session, event) => {\n      if (event.type !== 'turn/end') return\n      void autoPush(session).catch(error => warn(`auto push failed: ${messageOf(error)}`))\n    })\n  }\n\n  // 周期拉取（pullIntervalMinutes > 0 时；定时器随 fiber 自动撤销）。\n  if (resolved.pullIntervalMinutes > 0) {\n    ctx.effect(() => {\n      const timer = setInterval(() => {\n        void engine.pull().then(result => {\n          if (!result.ok) warn(`periodic pull failed: ${result.error ?? 'unknown error'}`)\n        })\n      }, resolved.pullIntervalMinutes * 60_000)\n      return () => clearInterval(timer)\n    }, `${PLUGIN_NAME}.periodic-pull`)\n  }\n}\n\nexport {\n  // 复用/测试面：引擎、后端、纯函数与词汇。\n  GitBackend,\n  SyncEngine,\n  EncryptedBackend,\n  selectEncryptionMode,\n  detectAge,\n  ageEncrypt,\n  ageDecrypt,\n  encryptTree,\n  decryptTree,\n  mergeTrees,\n  collectStatus,\n  renderStatus,\n  renderDiff,\n  renderPull,\n  renderPush,\n  confirmSync,\n  makeEventGate,\n  maybeAppendSessionEvent,\n  hasOpenTurn,\n  openTurnFromProjection,\n  resolveSessionRoot,\n  resolveRepoDir,\n  assertNestingSafe,\n  sessionSyncDomainSpec,\n  registryUnavailable,\n  errorValue,\n  // 跨平台 cwd 投影（#28）与符号链接诊断（#30）的复用/测试面。\n  normalizeCwdMap,\n  matchCwdMap,\n  projectCwd,\n  projectKey,\n  projectedRelOf,\n  planRestoreFile,\n  canonicalizeProjectedFile,\n  readProjectionState,\n  readSessionHeader,\n}\n"
    },
    {
      "path": "lib/engine.mjs",
      "content": "// lib/engine.mjs — 同步编排（业务层；DSH 服务经回调注入，本模块零 DSH 依赖）。\n//\n// 操作语义：\n// - push：镜像 → 提交 → push；被拒（远端领先）→ fetch + 拉取调和 → 重推一次；\n//   绝不强推。\n// - pull：先镜像 + 提交本地（保证合并基点是已提交状态）→ fetch → 三分支合并\n//   （lib/merge.mjs 的 append-only 语义）→ 合并提交。冲突双方字节永不丢弃：\n//   本地保留原路径，远端留存为 fork 文件。\n// - 全部操作经 git.schedule 串行（同一仓库互不穿插）。\n\nimport { promises as fs } from 'node:fs'\nimport path from 'node:path'\nimport { MERGE_KINDS, MIRROR_DIR, DEVICE_FILE, UNMAPPED_DIR } from './constants.mjs'\nimport { planMerge } from './merge.mjs'\nimport { mirrorSessionRoot, restoreSessionRoot, pruneRestoredSessions, ensureDeviceFile } from './mirror.mjs'\nimport { collectStatus } from './status.mjs'\nimport { forkFileName } from './paths.mjs'\nimport { messageOf, SyncError } from './errors.mjs'\nimport { redactText, sanitizeRemote } from './sanitize.mjs'\n\n/**\n * 同步引擎。\n * @typedef {object} EngineDeps\n * @property {import('./git.mjs').GitBackend} git - git 后端。\n * @property {string} sessionRoot - 会话存储根（绝对）。\n * @property {string} repoDir - 同步仓库根（绝对）。\n * @property {string} remote - 远端地址原文（展示时 sanitize）。\n * @property {string} branch - 分支名。\n * @property {string} deviceId - 设备 id（fork 归属）。\n * @property {ReadonlyArray<object>} [cwdMap] - 恢复期 cwd 投影表（最长前缀优先）。\n * @property {boolean} [followSessionSymlinks] - 镜像时是否跟随根内符号链接（#30；默认 false）。\n * @property {(patch: object) => void} reportMeta - 元数据补丁回调（index.mjs 写领域）。\n * @property {(message: string) => void} reportError - 最近错误回调（写领域 lastError）。\n * @property {(forkRelPaths: string[]) => void} onForks - fork 文件产生回调（index.mjs 做会话级 fork + 事件）。\n * @property {{debug: Function, info: Function, warn: Function, error: Function}} logger - 日志。\n */\nexport class SyncEngine {\n  /** @type {EngineDeps} */\n  #deps\n\n  /** @param {EngineDeps} deps - 依赖。 */\n  constructor(deps) {\n    this.#deps = deps\n  }\n\n  /** 设备 id（fork 文件名后缀；领域就绪后由 index.mjs 补齐）。 */\n  set deviceId(value) {\n    this.#deps.deviceId = value\n  }\n\n  /** 设备短 id（fork 文件名后缀，≤8 位小写十六进制）。 */\n  get deviceShort() {\n    return this.#deps.deviceId.replaceAll('-', '').slice(0, 8).toLowerCase() || 'unknown'\n  }\n\n  /** 串行执行一次同步操作（同仓库互斥）。 */\n  #schedule(fn) {\n    return this.#deps.git.schedule(fn)\n  }\n\n  /** 失败包装：脱敏 → reportError → 结构化错误结果。 */\n  #fail(error) {\n    const message = redactText(messageOf(error))\n    this.#deps.reportError(message)\n    this.#deps.logger.warn(`sync failed: ${message}`)\n    return { ok: false, error: message }\n  }\n\n  /** remote 未配置时响亮失败（状态类操作不拦）。 */\n  #requireRemote() {\n    if (this.#deps.remote === undefined || this.#deps.remote.trim() === '') {\n      throw new Error('no sync remote configured — set config.remote (status/diff work without one)')\n    }\n  }\n\n  /**\n   * 镜像 + 提交（push/pull 共用前置）。\n   * @returns {Promise<{deviceWritten: boolean, mirror: {mirrored: number, unchanged: number, deleted: string[], forkedPreserved: string[], skippedLinks: string[]}}>}\n   */\n  // 镜像（不提交）：把 sessionRoot 的字节镜像进工作树 + 确保设备文件。\n  // 只写本地工作树，不触网、不确认、不提交。调用方已持有 schedule 锁，\n  // 这里绝不能再走 #schedule。\n  async #mirrorOnly() {\n    const deviceWritten = await ensureDeviceFile(this.#deps.repoDir, DEVICE_FILE, this.#deps.deviceId)\n    const mirror = await mirrorSessionRoot({\n      sessionRoot: this.#deps.sessionRoot,\n      repoDir: this.#deps.repoDir,\n      mirrorDir: MIRROR_DIR,\n      followSessionSymlinks: this.#deps.followSessionSymlinks === true,\n    })\n    return { deviceWritten, mirror }\n  }\n\n  /**\n   * 镜像诊断（#28/#30）：跳过/跟随的符号链接、cwd 投影计数与告警。\n   * @param {object} mirror - mirrorSessionRoot 产物。\n   * @returns {{skippedSymlinks: number, skippedSymlinkPaths: string[], followedSymlinks: number, cwdMapped: number, cwdUnmapped: number, cwdProjectionSkipped: number, cwdPlaceholder: string, followSessionSymlinks: boolean, warnings: string[]}} 诊断。\n   */\n  #mirrorDiagnostics(mirror) {\n    const skipped = Array.isArray(mirror.skippedLinks) ? mirror.skippedLinks : []\n    const warnings = []\n    if (skipped.length > 0) {\n      const sample = skipped.slice(0, 5).join(', ')\n      warnings.push(`${skipped.length} file(s) under sessionRoot were skipped as symbolic links and are not mirrored (${sample}${skipped.length > 5 ? ', …' : ''}); set followSessionSymlinks: true to include links whose realpath stays inside sessionRoot`)\n    }\n    if ((mirror.cwdUnmapped ?? 0) > 0) {\n      warnings.push(`${mirror.cwdUnmapped} session(s) with a cross-platform cwd have no cwdMap entry; they are shown read-only under ${path.join(this.#deps.sessionRoot, UNMAPPED_DIR)}`)\n    }\n    if (typeof mirror.projectionError === 'string') {\n      warnings.push(`cwd projection state is unreadable: ${mirror.projectionError}`)\n    }\n    return {\n      skippedSymlinks: skipped.length,\n      skippedSymlinkPaths: skipped.slice(0, 20),\n      followedSymlinks: Array.isArray(mirror.followedLinks) ? mirror.followedLinks.length : 0,\n      cwdMapped: mirror.cwdMapped ?? 0,\n      cwdUnmapped: mirror.cwdUnmapped ?? 0,\n      cwdProjectionSkipped: mirror.cwdProjectionSkipped ?? 0,\n      cwdPlaceholder: path.join(this.#deps.sessionRoot, UNMAPPED_DIR),\n      followSessionSymlinks: this.#deps.followSessionSymlinks === true,\n      warnings,\n    }\n  }\n\n  // 前置镜像 + 提交。调用方（push/pull）已持有 schedule 锁，这里绝不能再走\n  // #schedule —— 嵌套 schedule 会在同一 git 链上自锁（fnM 等 fnP 完成、fnP 等 fnM）。\n  async #mirrorAndCommit(message) {\n    const { deviceWritten, mirror } = await this.#mirrorOnly()\n    if (deviceWritten || mirror.mirrored > 0 || mirror.deleted.length > 0) {\n      const committed = await this.#deps.git.commitAll(message)\n      return { ...mirror, committed }\n    }\n    return { ...mirror, committed: null }\n  }\n\n  /**\n   * 状态：先本地初始化 + 镜像（不提交），使未同步的会话变更以\"未提交文件\"\n   * 形式进入 dirty；只写本地工作树，不触网、不确认。\n   * @returns {Promise<{ok: boolean, branch?: string, remote?: string, head?: string, remoteHead?: string, ahead: number, behind: number, dirty: string[], forks: string[], diffStat: string, mergeInProgress: boolean, lastCommits: string[], error?: string}>}\n   */\n  status() {\n    return this.#schedule(async () => {\n      /** @type {object|undefined} */\n      let mirror\n      try {\n        await fs.mkdir(this.#deps.repoDir, { recursive: true })\n        await this.#deps.git.ensureRepo()\n        mirror = (await this.#mirrorOnly()).mirror\n      } catch {\n        // 初始化/镜像失败不阻断状态：collectStatus 会返回带 error 的快照。\n      }\n      const collected = await collectStatus(this.#deps.git, { branch: this.#deps.branch, remote: this.#deps.remote ?? '' })\n      if (mirror === undefined) return collected\n      const diagnostics = this.#mirrorDiagnostics(mirror)\n      return {\n        ...collected,\n        skippedSymlinks: diagnostics.skippedSymlinks,\n        skippedSymlinkPaths: diagnostics.skippedSymlinkPaths,\n        followedSymlinks: diagnostics.followedSymlinks,\n        cwdMapped: diagnostics.cwdMapped,\n        cwdUnmapped: diagnostics.cwdUnmapped,\n        cwdProjectionSkipped: diagnostics.cwdProjectionSkipped,\n        cwdPlaceholder: diagnostics.cwdPlaceholder,\n        followSessionSymlinks: diagnostics.followSessionSymlinks,\n        warnings: diagnostics.warnings,\n      }\n    })\n  }\n\n  /**\n   * 推送：镜像 → 提交 → push；被拒时拉取调和后重推一次。\n   * @param {object} [opts] - {signal?: AbortSignal}。\n   * @returns {Promise<{ok: boolean, pushed?: boolean, head?: string, mirrored?: number, deleted?: number, remote?: string, error?: string}>}\n   */\n  push(opts = {}) {\n    return this.#schedule(async () => {\n      try {\n        this.#requireRemote()\n        // git 命令以 repoDir 为 cwd，首次操作前必须保证它存在（cwd 缺失时\n        // spawn 静默失败，甚至伪装成 exit 0）。\n        await fs.mkdir(this.#deps.repoDir, { recursive: true })\n        await this.#deps.git.bootstrap()\n        const mirror = await this.#mirrorAndCommit('dsh-session-sync: push snapshot')\n        try {\n          await this.#deps.git.push({ signal: opts.signal })\n        } catch (error) {\n          if (!(error instanceof SyncError && error.code === 'PUSH_REJECTED')) {\n            throw error\n          }\n          // 远端领先：先拉取调和（保留双方），再重推一次。\n          this.#deps.logger.info('push rejected (remote moved); pulling and reconciling before one retry')\n          const pulled = await this.#pullInternal(opts)\n          if (!pulled.ok) throw error\n          await this.#deps.git.push({ signal: opts.signal })\n        }\n        const head = await this.#deps.git.headSha()\n        this.#deps.reportMeta({ lastPushAt: Date.now(), lastPushHead: head, lastError: undefined })\n        this.#deps.logger.info(`sync push ok: head ${head ?? ''} (${mirror.mirrored} mirrored, ${mirror.deleted} deleted)`)\n        const diagnostics = this.#mirrorDiagnostics(mirror)\n        return {\n          ok: true,\n          pushed: true,\n          head,\n          mirrored: mirror.mirrored,\n          deleted: mirror.deleted.length,\n          remote: sanitizeRemote(this.#deps.remote),\n          skippedSymlinks: diagnostics.skippedSymlinks,\n          skippedSymlinkPaths: diagnostics.skippedSymlinkPaths,\n          warnings: diagnostics.warnings,\n        }\n      } catch (error) {\n        return this.#fail(error)\n      }\n    })\n  }\n\n  /**\n   * 拉取：本地提交 → fetch → 三分支合并（append-only 语义）。\n   * @param {object} [opts] - {signal?: AbortSignal}。\n   * @returns {Promise<{ok: boolean, pulled?: boolean, merged?: boolean, adopted?: number, appended?: number, diverged?: number, forks?: string[], head?: string, error?: string}>}\n   */\n  pull(opts = {}) {\n    return this.#schedule(async () => {\n      try {\n        this.#requireRemote()\n        await fs.mkdir(this.#deps.repoDir, { recursive: true })\n        await this.#deps.git.bootstrap()\n        await this.#mirrorAndCommit('dsh-session-sync: local checkpoint before pull')\n        const result = await this.#pullInternal(opts)\n        // 成功的拉取清掉上一次的 lastError：它曾经永久保留，让用户按几天前的\n        // push 错误排查当前问题（#29）。\n        if (result.ok) this.#deps.reportMeta({ lastError: undefined })\n        return result\n      } catch (error) {\n        return this.#fail(error)\n      }\n    })\n  }\n\n  /**\n   * 拉取内部步骤（push 重试路径复用；前置已保证仓库存在且本地已提交）。\n   * @param {object} [opts] - {signal?: AbortSignal}。\n   * @returns {Promise<object>}\n   */\n  async #pullInternal(opts = {}) {\n    const fetched = await this.#deps.git.fetch({ signal: opts.signal })\n    if (!fetched) {\n      this.#deps.reportMeta({ lastPullAt: Date.now() })\n      return { ok: true, pulled: false, forks: [], adopted: 0, appended: 0, diverged: 0 }\n    }\n    const [head, remoteHead] = [await this.#deps.git.headSha(), await this.#deps.git.remoteHeadSha()]\n    if (remoteHead === undefined) {\n      this.#deps.reportMeta({ lastPullAt: Date.now() })\n      return { ok: true, pulled: false, forks: [], adopted: 0, appended: 0, diverged: 0 }\n    }\n    if (head === remoteHead) {\n      this.#deps.reportMeta({ lastPullAt: Date.now() })\n      return { ok: true, pulled: false, forks: [], adopted: 0, appended: 0, diverged: 0 }\n    }\n    const behind = await this.#deps.git.countCommitsSafe(head, remoteHead)\n    if (behind === 0) {\n      // 本地领先（远端无新提交）：无拉取内容。\n      this.#deps.reportMeta({ lastPullAt: Date.now() })\n      return { ok: true, pulled: false, forks: [], adopted: 0, appended: 0, diverged: 0 }\n    }\n    // 先清掉 stat-dirty：宿主原子写暂存文件会让 git 误判工作树有未提交改动，\n    // 从而在 merge 时走 autostash 并失败（#29）。\n    await this.#deps.git.refreshIndex()\n    const merged = await this.#deps.git.beginMerge(remoteHead)\n    if (!merged.inProgress) {\n      this.#deps.reportMeta({ lastPullAt: Date.now() })\n      return { ok: true, pulled: false, forks: [], adopted: 0, appended: 0, diverged: 0 }\n    }\n    let result\n    if (merged.conflicted) {\n      result = await this.#resolveConflicts()\n    } else {\n      result = { adopted: 0, appended: 0, diverged: 0, forks: [] }\n      await this.#deps.git.addAll()\n    }\n    const newHead = await this.#deps.git.commitMerge()\n    const mirrorRoot = path.join(this.#deps.repoDir, MIRROR_DIR)\n    const pruned = await pruneRestoredSessions({ repoDir: this.#deps.repoDir, mirrorRoot, sessionRoot: this.#deps.sessionRoot })\n    const restored = await restoreSessionRoot({\n      repoDir: this.#deps.repoDir,\n      mirrorRoot,\n      sessionRoot: this.#deps.sessionRoot,\n      cwdMap: this.#deps.cwdMap ?? [],\n    })\n    const pullWarnings = []\n    if (restored.cwdUnmapped > 0) {\n      pullWarnings.push(`${restored.cwdUnmapped} restored session(s) have a cross-platform cwd and no cwdMap entry; they are visible read-only under ${path.join(this.#deps.sessionRoot, UNMAPPED_DIR)}`)\n    }\n    if (restored.cwdProjectionSkipped > 0) {\n      pullWarnings.push(`${restored.cwdProjectionSkipped} session file(s) could not be cwd-projected (unreadable header or legacy layout) and keep the origin device's cwd`)\n    }\n    this.#deps.reportMeta({ lastPullAt: Date.now() })\n    this.#deps.logger.info(`sync pull ok: merged remote head ${remoteHead} → ${newHead ?? ''} (${result.appended} appended-both, ${result.diverged} diverged, ${result.forks.length} forks, ${restored.restored} restored, ${pruned.pruned.length} pulled-deletions)`)\n    if (result.forks.length > 0) this.#deps.onForks(result.forks)\n    return {\n      ok: true,\n      pulled: true,\n      merged: true,\n      adopted: result.adopted,\n      appended: result.appended,\n      diverged: result.diverged,\n      forks: result.forks,\n      restored: restored.restored,\n      cwdMapped: restored.cwdMapped,\n      cwdUnmapped: restored.cwdUnmapped,\n      head: newHead ?? undefined,\n      warnings: pullWarnings,\n    }\n  }\n\n  /**\n   * 冲突解决：逐路径分类 → ours/theirs 检出 → 远端侧留存为 fork 文件 →\n   * 全量暂存（提交由调用方落合并提交）。失败时 abortMerge 恢复。\n   *\n   * 删除/修改冲突（一侧删除、另一侧修改）同样走 keep-both：git 只为存在的一侧\n   * 登记 stage，缺失的一侧按「该侧删除了该文件」解释——删除意图保留，另一侧\n   * 按既有规则存续（远端内容仍以 fork 文件留存）。绝不因缺 stage 而中止整次 pull。\n   * @returns {Promise<{adopted: number, appended: number, diverged: number, forks: string[]}>}\n   */\n  async #resolveConflicts() {\n    try {\n      const conflicts = await this.#deps.git.conflictedPaths()\n      const entries = []\n      for (const conflict of conflicts) {\n        const [base, ours, theirs] = await Promise.all([\n          this.#deps.git.readStageBlob('1', conflict.path),\n          this.#deps.git.readStageBlob('2', conflict.path),\n          this.#deps.git.readStageBlob('3', conflict.path),\n        ])\n        entries.push({ path: conflict.path, base, ours, theirs })\n      }\n      const { resolutions, summary } = planMerge(entries)\n      /** 路径 → ours/theirs 字节；某侧缺失即该侧删除了该文件（git 不登记其 stage）。 */\n      const sides = new Map(entries.map(entry => [entry.path, entry]))\n      const forks = []\n      const now = new Date()\n      // 严格 14 位 UTC 戳（yyyyMMddHHmmss）：与 lib/encrypted.mjs 同口径剔除 ISO\n      // 分隔符（`-`/`:`/`T`）后再截断。仅去掉 `-`/`:` 会留下 `T`，使\n      // forkFileName 的 /^\\d{14}$/ 失配并静默回退到纪元戳。\n      const stamp = now.toISOString().replace(/[-:T]/gu, '').slice(0, 14)\n      for (const resolution of resolutions) {\n        const side = sides.get(resolution.path)\n        const hasOurs = side?.ours !== undefined\n        const hasTheirs = side?.theirs !== undefined\n        const absolute = path.join(this.#deps.repoDir, ...resolution.path.split('/'))\n        // `checkout --ours/--theirs` 对缺失的 stage 会失败（`does not have\n        // our/their version`），因此每一侧都先看它在冲突里是否存在。\n        if (resolution.adoptTheirs) {\n          if (hasTheirs) await this.#deps.git.checkoutStage('theirs', resolution.path)\n          else await fs.rm(absolute, { force: true })\n          continue\n        }\n        if (resolution.forkTheirs && hasTheirs) {\n          // 先取 theirs 工作树字节 → 写 fork 文件 → 再恢复 ours 侧。\n          await this.#deps.git.checkoutStage('theirs', resolution.path)\n          const content = await fs.readFile(absolute)\n          const forkName = forkFileName(path.posix.basename(resolution.path), stamp, this.deviceShort)\n          await fs.writeFile(path.join(path.dirname(absolute), forkName), content)\n          // ours 缺失＝本地已删除：保留删除，远端内容只以 fork 文件存续。\n          if (hasOurs) await this.#deps.git.checkoutStage('ours', resolution.path)\n          else await fs.rm(absolute, { force: true })\n          const forkRel = path.posix.join(path.posix.dirname(resolution.path), forkName)\n          forks.push(forkRel)\n          continue\n        }\n        // 远端已删除（theirs 缺失）：保留本地版本，分歧照常计入 summary.diverged。\n        if (hasOurs) await this.#deps.git.checkoutStage('ours', resolution.path)\n        else await fs.rm(absolute, { force: true })\n      }\n      await this.#deps.git.addAll()\n      return { adopted: summary.adopted, appended: summary.appended, diverged: summary.diverged, forks }\n    } catch (error) {\n      try {\n        await this.#deps.git.abortMerge()\n      } catch {\n        // 恢复失败以原始错误为主，恢复失败只记录。\n      }\n      throw error\n    }\n  }\n}\n\nexport { MERGE_KINDS }\n"
    },
    {
      "path": "lib/merge.mjs",
      "content": "// lib/merge.mjs — append-only 三分支合并语义（纯函数，零依赖）。\n//\n// 会话日志是 append-only：三方（合并基点 base、本地 ours、远端 theirs）\n// 逐文件按字节比较。规则（绝不静默覆盖——ours/theirs 任一字节都会存续）：\n// - 相同（ours == theirs）→ 保留 ours；\n// - 仅本地变（theirs == base）→ 保留 ours；\n// - 仅远端变（ours == base）→ 采纳 theirs（本地无增量可丢，不是覆盖）；\n// - 双边纯追加（base 是 ours 与 theirs 的共同字节前缀）→ 保留 ours 在原路径，\n//   theirs 整体留存为 fork 文件（两边保留）；\n// - 其余（任一侧重写/压缩打包/删除等真实分歧）→ 同样保留 ours + fork theirs，\n//   并响亮报告 diverged，绝不替用户取舍。\n//\n// 内容按 Buffer 语义比较：zstd 等二进制日志与 UTF-8 文本同一套规则。\n\nimport { MERGE_KINDS } from './constants.mjs'\n\n/** 任意内容形态 → Buffer|undefined。 */\nfunction norm(value) {\n  if (value === undefined || value === null) return undefined\n  if (Buffer.isBuffer(value)) return value\n  return Buffer.from(String(value))\n}\n\n/** a 是否为 b 的字节前缀（等长即相等）。 */\nfunction isPrefix(prefix, whole) {\n  return prefix !== undefined && whole !== undefined\n    && prefix.length <= whole.length\n    && whole.subarray(0, prefix.length).equals(prefix)\n}\n\n/**\n * 单路径三方分类。\n * @param {Buffer|string|undefined} base - 合并基点内容。\n * @param {Buffer|string|undefined} ours - 本地内容。\n * @param {Buffer|string|undefined} theirs - 远端内容。\n * @returns {{kind: string, keepOurs: boolean, forkTheirs: boolean}}\n *   kind ∈ MERGE_KINDS；keepOurs=false 时采纳 theirs（theirs-only）。\n */\nexport function classifyPath(base, ours, theirs) {\n  const b = norm(base)\n  const o = norm(ours)\n  const t = norm(theirs)\n  if (o !== undefined && t !== undefined && o.equals(t)) {\n    return { kind: MERGE_KINDS.IDENTICAL, keepOurs: true, forkTheirs: false }\n  }\n  if (o === undefined && t === undefined) {\n    return { kind: MERGE_KINDS.IDENTICAL, keepOurs: true, forkTheirs: false }\n  }\n  // 仅本地变：远端仍是基点内容。\n  if (equalsOrBothMissing(t, b)) {\n    return { kind: MERGE_KINDS.OURS_ONLY, keepOurs: true, forkTheirs: false }\n  }\n  // 仅远端变：本地仍是基点内容 → 采纳远端（本地无增量，非覆盖）。\n  if (equalsOrBothMissing(o, b)) {\n    return { kind: MERGE_KINDS.THEIRS_ONLY, keepOurs: false, forkTheirs: false }\n  }\n  // 双边纯追加：共同基点前缀 + 各自后缀 → 两边保留，远端转 fork 文件。\n  if (isPrefix(b, o) && isPrefix(b, t)) {\n    return { kind: MERGE_KINDS.APPEND_BOTH, keepOurs: true, forkTheirs: true }\n  }\n  // 真实分歧（重写/打包/单侧删除等）：同样两边保留 + 响亮报告。\n  return { kind: MERGE_KINDS.DIVERGED, keepOurs: true, forkTheirs: true }\n}\n\n/** 两侧同时缺失或字节相等。 */\nfunction equalsOrBothMissing(left, right) {\n  if (left === undefined && right === undefined) return true\n  if (left === undefined || right === undefined) return false\n  return left.equals(right)\n}\n\n/**\n * 整批冲突路径的合并计划（pull 阶段对 merge 冲突路径逐一调用 classifyPath）。\n * @param {Array<{path: string, base?: Buffer|string, ours?: Buffer|string, theirs?: Buffer|string}>} conflicts - 冲突路径。\n * @returns {{resolutions: Array<{path: string, kind: string, adoptTheirs: boolean, forkTheirs: boolean}>, summary: {kept: number, adopted: number, appended: number, diverged: number, forkPaths: string[]}}}\n */\nexport function planMerge(conflicts) {\n  const resolutions = []\n  const summary = { kept: 0, adopted: 0, appended: 0, diverged: 0, forkPaths: [] }\n  for (const entry of conflicts) {\n    const verdict = classifyPath(entry.base, entry.ours, entry.theirs)\n    const resolution = {\n      path: entry.path,\n      kind: verdict.kind,\n      adoptTheirs: !verdict.keepOurs,\n      forkTheirs: verdict.forkTheirs,\n    }\n    resolutions.push(resolution)\n    if (verdict.kind === MERGE_KINDS.THEIRS_ONLY) summary.adopted += 1\n    else summary.kept += 1\n    if (verdict.kind === MERGE_KINDS.APPEND_BOTH) summary.appended += 1\n    if (verdict.kind === MERGE_KINDS.DIVERGED) summary.diverged += 1\n    if (verdict.forkTheirs) summary.forkPaths.push(entry.path)\n  }\n  return { resolutions, summary }\n}\n"
    },
    {
      "path": "lib/mirror.mjs",
      "content": "// lib/mirror.mjs — 会话目录 → git 工作树的字节镜像（node:fs；零 DSH 依赖）。\n//\n// 会话文件一律按不透明字节复制（JSONL/zstd 等物理编码属于宿主，插件不解析）。\n// 安全边界：\n// - 默认绝不跟随符号链接（源或目标为链接一律跳过并报告，杜绝写出根外）；\n//   `followSessionSymlinks: true` 时只跟随 realpath 仍落在 sessionRoot 内的链接\n//   （proot link2symlink 那类\"可读但 dirent 报 symlink\"的宿主，见 #30）；\n// - 删除仅限工作树内、源已不存在、且非 fork 文件、非宿主私有产物的常规文件；\n// - fork 文件（FORK_NAME_RE）永不复制、永不删除——冲突双方字节的持久载体；\n// - 宿主私有会话产物（HOST_ARTIFACT_NAME_RE：session.lock / 迁移暂存）同样\n//   永不复制、永不删除——运行时状态不属于可同步内容。\n//\n// 跨平台 cwd 投影（#28）：恢复时把 header.cwd 投成本机路径、文件落到宿主布局的\n// 投影位置；镜像里的字节仍是原设备的 header（见 lib/projection.mjs）。镜像枚举\n// 因此跳过投影位置，并按投影表把本地尾部接回镜像里的原首帧——推送出去的字节\n// 与对端追加的字节逐字节一致。\n\nimport { promises as fs } from 'node:fs'\nimport path from 'node:path'\nimport { createHash } from 'node:crypto'\nimport { FORK_NAME_RE, HOST_ARTIFACT_NAME_RE, UNMAPPED_DIR } from './constants.mjs'\nimport {\n  canonicalizeProjectedFile,\n  planRestoreFile,\n  readProjectionState,\n  writeProjectionState,\n} from './projection.mjs'\n\n/** 跟随符号链接时允许的最大目录深度（防环耗尽栈）。 */\nconst MAX_WALK_DEPTH = 64\n\n/** 符号链接的 realpath 是否仍在 root 内（真实路径 containment）。 */\nfunction insideRoot(rootReal, targetReal) {\n  const rel = path.relative(rootReal, targetReal)\n  return rel === '' || (!rel.startsWith('..') && !path.isAbsolute(rel))\n}\n\n/**\n * 递归枚举 root 下全部常规文件（POSIX 相对路径；符号链接默认跳过并回报）。\n * 跟随边界：只有当链接的 realpath 仍落在 `realpath(root)` 内时才读取/递归；\n * 越界链接仍进 `skipped`。目录链接用 realpath 去环。\n * @param {string} root - 会话存储根。\n * @param {{followSymlinks?: boolean}} [options] - 是否跟随根内符号链接。\n * @returns {Promise<{files: {absolute: string, rel: string}[], skipped: string[], followed: string[]}>} 枚举结果。\n */\nasync function listFiles(root, options = {}) {\n  const followSymlinks = options.followSymlinks === true\n  const files = []\n  const skipped = []\n  const followed = []\n  const seenFiles = new Set()\n  const rootReal = followSymlinks ? await fs.realpath(root) : undefined\n  const visitedDirectories = new Set()\n  const walk = async (dir, depth) => {\n    const entries = await fs.readdir(dir, { withFileTypes: true })\n    for (const entry of entries) {\n      const absolute = path.join(dir, entry.name)\n      const rel = path.relative(root, absolute).split(path.sep).join('/')\n      if (entry.isSymbolicLink()) {\n        if (!followSymlinks) {\n          skipped.push(absolute)\n          continue\n        }\n        if (depth > MAX_WALK_DEPTH) {\n          skipped.push(absolute)\n          continue\n        }\n        let targetReal\n        try {\n          targetReal = await fs.realpath(absolute)\n        } catch {\n          skipped.push(absolute)\n          continue\n        }\n        if (!insideRoot(/** @type {string} */ (rootReal), targetReal)) {\n          skipped.push(absolute)\n          continue\n        }\n        let stats\n        try {\n          stats = await fs.stat(absolute)\n        } catch {\n          skipped.push(absolute)\n          continue\n        }\n        if (stats.isDirectory()) {\n          if (visitedDirectories.has(targetReal)) continue\n          visitedDirectories.add(targetReal)\n          followed.push(rel)\n          await walk(absolute, depth + 1)\n          continue\n        }\n        if (stats.isFile()) {\n          if (seenFiles.has(rel)) continue\n          seenFiles.add(rel)\n          files.push({ absolute, rel })\n          followed.push(rel)\n          continue\n        }\n        skipped.push(absolute)\n        continue\n      }\n      if (entry.isDirectory()) {\n        if (followSymlinks) {\n          try {\n            const real = await fs.realpath(absolute)\n            if (visitedDirectories.has(real)) continue\n            visitedDirectories.add(real)\n          } catch {\n            continue\n          }\n        }\n        await walk(absolute, depth + 1)\n        continue\n      }\n      if (entry.isFile()) {\n        if (seenFiles.has(rel)) continue\n        seenFiles.add(rel)\n        files.push({ absolute, rel })\n      }\n    }\n  }\n  await walk(root, 0)\n  return { files, skipped, followed }\n}\n\n/** 拒绝任何解析后落在 root 之外的写入（含父目录 symlink 逃逸）。 */\nasync function assertWriteInside(root, target) {\n  let rootReal\n  try { rootReal = await fs.realpath(root) } catch {\n    await fs.mkdir(root, { recursive: true })\n    rootReal = await fs.realpath(root)\n  }\n  await fs.mkdir(path.dirname(target), { recursive: true })\n  const parentReal = await fs.realpath(path.dirname(target))\n  const rel = path.relative(rootReal, parentReal)\n  if (rel.startsWith('..') || path.isAbsolute(rel)) throw new Error(`refusing to write outside ${rootReal}`)\n}\n\n/** 内容一致则跳过写（返回 false），否则覆写（返回 true）。root 可选，提供时做真实路径 containment。 */\nasync function writeIfDifferent(target, content, root) {\n  if (root !== undefined) await assertWriteInside(root, target)\n  try {\n    const st = await fs.lstat(target)\n    if (st.isSymbolicLink()) throw new Error('refusing to write through a symbolic link')\n  } catch (error) {\n    if (error?.code !== 'ENOENT') throw error\n  }\n  try {\n    const existing = await fs.readFile(target)\n    if (existing.equals(content)) return false\n  } catch {\n    // 目标不存在 → 照写。\n  }\n  await fs.mkdir(path.dirname(target), { recursive: true })\n  try {\n    await fs.writeFile(target, content)\n  } catch (error) {\n    // 只读投影副本（占位目录）由本插件写成 0o444；再次恢复前先解开写位。\n    if (error?.code !== 'EACCES' && error?.code !== 'EPERM') throw error\n    await fs.chmod(target, 0o644).catch(() => {})\n    await fs.writeFile(target, content)\n  }\n  return true\n}\n\n/** 删除文件；只读投影副本（占位目录 0o444）在 Windows 上先解开只读位再删。 */\nasync function unlinkFile(target) {\n  try {\n    await fs.unlink(target)\n  } catch (error) {\n    if (error?.code !== 'EACCES' && error?.code !== 'EPERM') throw error\n    await fs.chmod(target, 0o644).catch(() => {})\n    await fs.unlink(target)\n  }\n}\n\n/** 源快照状态文件：本地、不进提交、不随仓库同步。 */\nexport const SOURCE_SNAPSHOT_FILE = path.join('.git', 'dsh-session-sync-mirror.json')\n\n/** @param {string} repoDir */\nasync function readSourceSnapshot(repoDir) {\n  try {\n    const raw = await fs.readFile(path.join(repoDir, SOURCE_SNAPSHOT_FILE), 'utf8')\n    const parsed = JSON.parse(raw)\n    if (parsed === null || typeof parsed !== 'object' || !Array.isArray(parsed.sourcePaths)) return undefined\n    return new Set(parsed.sourcePaths.filter(rel => typeof rel === 'string'))\n  } catch {\n    return undefined\n  }\n}\n\n/** @param {string} repoDir @param {Set<string>} sourcePaths */\nasync function writeSourceSnapshot(repoDir, sourcePaths) {\n  const target = path.join(repoDir, SOURCE_SNAPSHOT_FILE)\n  const payload = Buffer.from(`${JSON.stringify({ version: 1, sourcePaths: [...sourcePaths].sort() })}\n`)\n  try {\n    const st = await fs.stat(path.dirname(target))\n    if (!st.isDirectory()) return\n  } catch {\n    return\n  }\n  await writeIfDifferent(target, payload)\n}\n\n/**\n * 把 sessionRoot 镜像进 <repoDir>/<mirrorDir>/…。\n * 宿主私有会话产物（租约/迁移暂存，HOST_ARTIFACT_NAME_RE）既不复制、也不删除：\n * 它们是运行时状态，同步它们只会把某设备的瞬时状态变成另一侧的删除/噪音。\n * 跨平台 cwd 投影：投影位置（`projectedRel`）不作为镜像源；对应条目按投影表\n * 把本地追加尾部接回镜像首帧后写入**原路径**，镜像字节因此保持原设备视角。\n * @param {object} deps - {sessionRoot, repoDir, mirrorDir, forkNameRe?, followSessionSymlinks?, projectionState?}。\n * @returns {Promise<{mirrored: number, unchanged: number, skippedLinks: string[], followedLinks: string[], deleted: string[], remotePreserved: string[], snapshotUnknown: boolean, forkedPreserved: string[], hostArtifactsSkipped: number, hostArtifactsPreserved: string[], cwdMapped: number, cwdUnmapped: number, cwdProjectionSkipped: number, projectionError?: string}>}\n */\nexport async function mirrorSessionRoot(deps) {\n  const forkRe = deps.forkNameRe ?? FORK_NAME_RE\n  const projectionState = deps.projectionState ?? await readProjectionState(deps.repoDir)\n  const projectedRels = new Set(projectionState.entries.map(entry => entry.projectedRel))\n  const source = await listFiles(deps.sessionRoot, { followSymlinks: deps.followSessionSymlinks === true })\n  const mirrorRoot = path.join(deps.repoDir, deps.mirrorDir)\n  const targets = new Set()\n  const previous = await readSourceSnapshot(deps.repoDir)\n\n  let mirrored = 0\n  let unchanged = 0\n  let hostArtifactsSkipped = 0\n  let cwdProjectionSkipped = 0\n  let cwdMapped = 0\n  let cwdUnmapped = 0\n  for (const file of source.files) {\n    if (projectedRels.has(file.rel)) continue\n    if (HOST_ARTIFACT_NAME_RE.test(path.posix.basename(file.rel))) {\n      hostArtifactsSkipped += 1\n      continue\n    }\n    const target = path.join(mirrorRoot, ...file.rel.split('/'))\n    targets.add(file.rel)\n    const wrote = await writeIfDifferent(target, await fs.readFile(file.absolute), deps.repoDir)\n    if (wrote) mirrored += 1\n    else unchanged += 1\n  }\n\n  // 投影条目：本地投影副本存在 → 镜像原路径必须继续受保护（删除保护），\n  // 且只在可推送（非占位只读）时把本地尾部接回原首帧后覆写。\n  for (const entry of projectionState.entries) {\n    let local\n    const localPath = path.join(deps.sessionRoot, ...entry.projectedRel.split('/'))\n    try {\n      const localStat = await fs.lstat(localPath)\n      // 投影副本必须是常规文件：绝不经符号链接读取（根内跟随只对镜像源开放）。\n      if (localStat.isSymbolicLink() || !localStat.isFile()) continue\n      local = await fs.readFile(localPath)\n    } catch {\n      continue\n    }\n    targets.add(entry.canonicalRel)\n    let mirrorExisting\n    try {\n      mirrorExisting = await fs.readFile(path.join(mirrorRoot, ...entry.canonicalRel.split('/')))\n    } catch {\n      mirrorExisting = undefined\n    }\n    // 占位（只读视图）永不作为推送源；可映射条目要求本地首帧仍是投影形状。\n    if (entry.readOnly === true) {\n      cwdUnmapped += 1\n      continue\n    }\n    const canonical = canonicalizeProjectedFile({ entry, localContent: local, mirrorContent: mirrorExisting })\n    if (canonical === undefined) {\n      cwdProjectionSkipped += 1\n      continue\n    }\n    cwdMapped += 1\n    const wrote = await writeIfDifferent(path.join(mirrorRoot, ...entry.canonicalRel.split('/')), canonical, deps.repoDir)\n    if (wrote) mirrored += 1\n    else unchanged += 1\n  }\n\n  // 删除：目标树中源已不存在、且非 fork 命名、非宿主私有产物的文件。\n  const deleted = []\n  const remotePreserved = []\n  const forkedPreserved = []\n  const hostArtifactsPreserved = []\n  const targetFiles = []\n  try {\n    const walk = async (dir) => {\n      const entries = await fs.readdir(dir, { withFileTypes: true })\n      for (const entry of entries) {\n        const absolute = path.join(dir, entry.name)\n        if (entry.isSymbolicLink()) continue\n        if (entry.isDirectory()) {\n          await walk(absolute)\n          continue\n        }\n        if (entry.isFile()) targetFiles.push(absolute)\n      }\n    }\n    await walk(mirrorRoot)\n  } catch {\n    // 镜像根尚不存在 → 无删除可做。\n  }\n  for (const absolute of targetFiles) {\n    const rel = path.relative(mirrorRoot, absolute).split(path.sep).join('/')\n    const basename = path.posix.basename(rel)\n    if (forkRe.test(basename)) {\n      forkedPreserved.push(rel)\n      continue\n    }\n    if (HOST_ARTIFACT_NAME_RE.test(basename)) {\n      hostArtifactsPreserved.push(rel)\n      continue\n    }\n    if (targets.has(rel)) continue\n    if (previous === undefined || !previous.has(rel)) {\n      // Never delete a file this device did not previously mirror from its own\n      // sessionRoot: it arrived via pull, or provenance is unknown.\n      remotePreserved.push(rel)\n      continue\n    }\n    await fs.unlink(absolute)\n    deleted.push(rel)\n  }\n  await writeSourceSnapshot(deps.repoDir, targets)\n\n  return {\n    mirrored,\n    unchanged,\n    skippedLinks: source.skipped,\n    followedLinks: source.followed,\n    deleted,\n    remotePreserved,\n    snapshotUnknown: previous === undefined,\n    forkedPreserved,\n    hostArtifactsSkipped,\n    hostArtifactsPreserved,\n    cwdMapped,\n    cwdUnmapped,\n    cwdProjectionSkipped,\n    projectionError: projectionState.error,\n  }\n}\n\n/** 恢复状态文件：本地、不进提交、不随仓库同步。 */\nexport const RESTORE_STATE_FILE = path.join('.git', 'dsh-session-sync-restored.json')\n\n/** @param {Buffer|string} content */\nfunction hashContent(content) {\n  return createHash('sha256').update(content).digest('hex')\n}\n\n/** @param {string} repoDir */\nasync function readRestoreState(repoDir) {\n  try {\n    const raw = await fs.readFile(path.join(repoDir, RESTORE_STATE_FILE), 'utf8')\n    const parsed = JSON.parse(raw)\n    if (parsed === null || typeof parsed !== 'object' || parsed.version !== 1 || parsed.files === null || typeof parsed.files !== 'object') return new Map()\n    return new Map(Object.entries(parsed.files).filter(([rel, hash]) => typeof rel === 'string' && typeof hash === 'string'))\n  } catch {\n    return new Map()\n  }\n}\n\n/** @param {string} repoDir @param {Map<string,string>} files */\nasync function writeRestoreState(repoDir, files) {\n  const target = path.join(repoDir, RESTORE_STATE_FILE)\n  const payload = Buffer.from(`${JSON.stringify({ version: 1, files: Object.fromEntries([...files].sort(([a], [b]) => a.localeCompare(b))) })}\n`)\n  try {\n    const st = await fs.stat(path.dirname(target))\n    if (!st.isDirectory()) return\n  } catch {\n    return\n  }\n  await writeIfDifferent(target, payload)\n}\n\n/** @param {string} root */\nasync function mirrorRelSet(root) {\n  const set = new Set()\n  try {\n    const entries = await fs.readdir(root, { recursive: true, withFileTypes: true })\n    for (const entry of entries) {\n      if (!entry.isFile()) continue\n      const parent = entry.parentPath ?? entry.path ?? root\n      set.add(path.relative(root, path.join(parent, entry.name)).split(path.sep).join('/'))\n    }\n  } catch {}\n  return set\n}\n\n/**\n * 删除本插件曾经从某次 pull 恢复、且远端随后删除的本机副本；只有当前字节仍等于\n * 记录的哈希时才删（用户改过的副本保留并照常推送）。投影位置通过投影表映射回\n * 镜像相对路径。\n * @param {{repoDir: string, mirrorRoot: string, sessionRoot: string, projectionState?: object}} deps\n * @returns {Promise<{pruned: string[], keptEdited: string[]}>}\n */\nexport async function pruneRestoredSessions(deps) {\n  const state = await readRestoreState(deps.repoDir)\n  if (state.size === 0) return { pruned: [], keptEdited: [] }\n  const projectionState = deps.projectionState ?? await readProjectionState(deps.repoDir)\n  const mirror = await mirrorRelSet(deps.mirrorRoot)\n  const pruned = []\n  const keptEdited = []\n  for (const [rel, expected] of [...state]) {\n    const canonicalRel = projectionState.byProjected.get(rel)?.canonicalRel ?? rel\n    if (mirror.has(canonicalRel)) continue\n    const target = path.join(deps.sessionRoot, ...rel.split('/'))\n    try {\n      const st = await fs.lstat(target)\n      if (st.isSymbolicLink()) { state.delete(rel); continue }\n      const content = await fs.readFile(target)\n      if (hashContent(content) === expected) {\n        await unlinkFile(target)\n        pruned.push(rel)\n      } else {\n        keptEdited.push(rel)\n      }\n    } catch {\n      // already gone\n    }\n    state.delete(rel)\n  }\n  await writeRestoreState(deps.repoDir, state)\n  return { pruned, keptEdited }\n}\n\n/**\n * Copy the merged mirror back into the live session store. Pull used to merge only\n * into the mirror; the next push then saw those files as \"missing locally\" and\n * unlinked them. This writes new/changed regular files back, never deletes,\n * never follows symlinks, and never writes fork files or host-private artifacts.\n *\n * 跨平台 cwd 投影（#28）：需要投影的会话写到宿主布局的投影位置\n * （`<projectKey(投影 cwd)>/<sessionId>/<file>`）并改写首帧 cwd；镜像里的原\n * 路径不落盘（同一会话 id 不能同时出现在两个项目目录）。投影表落在本地\n * `.git/` 下，推送时用于把原首帧接回。\n * @param {object} deps - {repoDir, mirrorRoot, sessionRoot, forkNameRe?, cwdMap?, platform?}。\n * @returns {Promise<{restored: number, unchanged: number, skipped: number, tracked: number, cwdMapped: number, cwdUnmapped: number, cwdProjectionSkipped: number, projectionError?: string}>}\n */\nexport async function restoreSessionRoot(deps) {\n  const forkRe = deps.forkNameRe ?? FORK_NAME_RE\n  const mirrorRoot = deps.mirrorRoot\n  let entries\n  try {\n    entries = await fs.readdir(mirrorRoot, { recursive: true, withFileTypes: true })\n  } catch {\n    return { restored: 0, unchanged: 0, skipped: 0, tracked: 0, cwdMapped: 0, cwdUnmapped: 0, cwdProjectionSkipped: 0 }\n  }\n  const previous = await readProjectionState(deps.repoDir)\n  const nextEntries = []\n  const nextRelSet = new Set()\n  let restored = 0\n  let unchanged = 0\n  let skipped = 0\n  let cwdMapped = 0\n  let cwdUnmapped = 0\n  let cwdProjectionSkipped = 0\n  const state = deps.repoDir === undefined ? new Map() : await readRestoreState(deps.repoDir)\n  for (const entry of entries) {\n    if (!entry.isFile()) { skipped += 1; continue }\n    const parent = entry.parentPath ?? entry.path ?? mirrorRoot\n    const absolute = path.join(parent, entry.name)\n    const rel = path.relative(mirrorRoot, absolute).split(path.sep).join('/')\n    const basename = path.posix.basename(rel)\n    if (forkRe.test(basename) || HOST_ARTIFACT_NAME_RE.test(basename)) { skipped += 1; continue }\n    const content = await fs.readFile(absolute)\n    const plan = planRestoreFile({\n      content,\n      mirrorRel: rel,\n      cwdMap: deps.cwdMap ?? [],\n      sessionRoot: deps.sessionRoot,\n      platform: deps.platform,\n    })\n    if (plan.kind === 'skipped') {\n      cwdProjectionSkipped += 1\n      // 无法投影（如 id 与目录不符）：保持镜像原样落盘，绝不写坏布局。\n    }\n    if (plan.kind === 'mapped') cwdMapped += 1\n    if (plan.kind === 'placeholder') cwdUnmapped += 1\n    if (plan.entry !== undefined) {\n      nextEntries.push(plan.entry)\n      // 映射目标 / 占位目录必须真实存在，宿主才能 realpath 并把它归入 workspace\n      // （失败不影响可读性：会话仍会以 ungrouped 出现在列表里）。\n      await fs.mkdir(plan.entry.projectedCwd, { recursive: true }).catch(() => {})\n    }\n    nextRelSet.add(plan.rel)\n    const target = path.join(deps.sessionRoot, ...plan.rel.split('/'))\n    let existed = false\n    try {\n      const st = await fs.lstat(target)\n      if (st.isSymbolicLink()) { skipped += 1; continue }\n      existed = true\n    } catch { /* target absent */ }\n    const wrote = await writeIfDifferent(target, plan.content, deps.sessionRoot)\n    if (wrote) restored += 1\n    else unchanged += 1\n    // 占位投影是只读视图：尽力在文件系统层面也标注只读（root 可写时由推送端\n    // 兜底——占位条目永不作为推送源）。\n    if (plan.kind === 'placeholder') await fs.chmod(target, 0o444).catch(() => {})\n    // Track only copies this plugin created (target absent before) or already\n    // tracked. A pre-existing user file is never claimed by the sync plugin.\n    if (!existed || state.has(plan.rel)) state.set(plan.rel, hashContent(plan.content))\n    // 投影位置与原路径不同：清掉旧版或旧映射遗留在原路径上的本机副本，否则\n    // 宿主会把同一 session id 看成两个项目里的重复会话。\n    if (plan.rel !== rel) {\n      const legacyTarget = path.join(deps.sessionRoot, ...rel.split('/'))\n      let legacyStat\n      try {\n        legacyStat = await fs.lstat(legacyTarget)\n      } catch {\n        legacyStat = undefined\n      }\n      if (legacyStat?.isFile() === true) {\n        const legacyContent = await fs.readFile(legacyTarget)\n        const tracked = state.get(rel)\n        if (legacyContent.equals(content) || (tracked !== undefined && hashContent(legacyContent) === tracked)) {\n          await unlinkFile(legacyTarget)\n          state.delete(rel)\n        }\n      }\n    }\n  }\n  // 失效投影清理：配置变更（映射删除/改写）后，旧投影位置上的副本若仍是本插件\n  // 写的字节，就删掉；否则保留并让状态记录它（用户改动优先）。\n  for (const oldEntry of previous.entries) {\n    if (nextRelSet.has(oldEntry.projectedRel)) continue\n    const oldTarget = path.join(deps.sessionRoot, ...oldEntry.projectedRel.split('/'))\n    let oldStat\n    try {\n      oldStat = await fs.lstat(oldTarget)\n    } catch {\n      oldStat = undefined\n    }\n    if (oldStat?.isFile() !== true) continue\n    const expected = state.get(oldEntry.projectedRel)\n    try {\n      const oldContent = await fs.readFile(oldTarget)\n      // 只删\"本插件上次恢复、且此后没人改动\"的副本：无哈希记录或字节已变都保留\n      // （用户改动优先，宁可留下一个可见副本也不误删数据）。\n      if (expected !== undefined && hashContent(oldContent) === expected) {\n        await unlinkFile(oldTarget)\n        state.delete(oldEntry.projectedRel)\n      }\n    } catch {\n      // 读不到就不删（安全优先）。\n    }\n  }\n  if (deps.repoDir !== undefined) {\n    await writeRestoreState(deps.repoDir, state)\n    await writeProjectionState(deps.repoDir, nextEntries)\n  }\n  return {\n    restored,\n    unchanged,\n    skipped,\n    tracked: state.size,\n    cwdMapped,\n    cwdUnmapped,\n    cwdProjectionSkipped,\n    projectionError: previous.error,\n  }\n}\n\n/**\n * 确保设备身份文件内容为 deviceId（不同才写；返回是否写入）。\n * @param {string} repoDir - 同步仓库根。\n * @param {string} deviceFile - 文件名（repoDir 直下）。\n * @param {string} deviceId - 设备 id。\n * @returns {Promise<boolean>} 是否写入。\n */\nexport async function ensureDeviceFile(repoDir, deviceFile, deviceId) {\n  const target = path.join(repoDir, deviceFile)\n  const content = Buffer.from(`${deviceId}\\n`)\n  return writeIfDifferent(target, content)\n}\n\nexport { UNMAPPED_DIR }\n"
